export const BOOK_DOCUMENT: string = "<!DOCTYPE html><html lang='ko'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width, initial-scale=1'><title>알뜰폰의 다음 10년 — 1,000만 회선 이후의 생존 전략</title><link rel='preconnect' href='https://cdn.jsdelivr.net' crossorigin><link rel='stylesheet' href='https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/static/pretendard.min.css'><style>/* =====================================================================\r\n   html-pastel-style · Pastel Card Design System\r\n   Clean, document-grade pastel cards. Pretendard + soft tints + depth.\r\n   Load Pretendard in <head>:\r\n   <link rel=\"stylesheet\"\r\n     href=\"https://cdn.jsdelivr.net/gh/orioncactus/pretendard@v1.3.9/dist/web/static/pretendard.min.css\">\r\n   ===================================================================== */\r\n\r\n:root{\r\n  /* ---- neutrals ---- */\r\n  --ink:#19223C; --text:#37415C; --muted:#6C748C; --faint:#9AA1B4;\r\n  --bg:#F3F5FB; --card:#FFFFFF; --line:#E6E9F2; --line2:#EEF1F8;\r\n  --accent:#2F55C6; --accent-soft:#E9EFFD; --accent-ink:#21408F;\r\n  --navy:#16386E; --navy-bg:#EAF1FB; --navy-bg2:#D9E6F6; --navy-bd:#C8DAF1;\r\n  --radius:18px;\r\n  --shadow-sm:0 1px 2px rgba(20,30,60,.05);\r\n  --shadow-md:0 1px 2px rgba(20,30,60,.04), 0 14px 32px rgba(20,30,60,.07);\r\n  --shadow-inset:0 2px 10px rgba(20,30,60,.06);\r\n\r\n  /* ---- pastel families: bg / bg2(deeper) / border / accent / deep(ink) ---- */\r\n  --sky-bg:#EAF2FE;   --sky-bg2:#D7E7FD;   --sky-bd:#CBDDFB;   --sky-ac:#3D7BEA;   --sky-dp:#1B4DA0;\r\n  --orange-bg:#FCEBDA; --orange-bg2:#F9D8BC; --orange-bd:#F5CDA6; --orange-ac:#EA6A17; --orange-dp:#A8500F;\r\n  --violet-bg:#F1EAFB;--violet-bg2:#E6DAF7;--violet-bd:#DFD0F5;--violet-ac:#875AD2;--violet-dp:#653A9F;\r\n  --amber-bg:#FBF3D9; --amber-bg2:#F6E8BC; --amber-bd:#F0E0AE; --amber-ac:#D2A11C; --amber-dp:#8A6912;\r\n  --mint-bg:#E6F5EE;  --mint-bg2:#D2EEDE;  --mint-bd:#C8E7D7;  --mint-ac:#2C9F70;  --mint-dp:#1C744E;\r\n  --peach-bg:#FDEEE6; --peach-bg2:#FADFCF; --peach-bd:#F8D6C5; --peach-ac:#E0784C; --peach-dp:#B0512B;\r\n}\r\n\r\n*{box-sizing:border-box}\r\nhtml{-webkit-text-size-adjust:100%}\r\nbody{\r\n  margin:0;\r\n  background:\r\n    radial-gradient(1100px 460px at 50% -240px, #fff 0%, rgba(255,255,255,0) 70%),\r\n    var(--bg);\r\n  color:var(--text);\r\n  font-family:\"Pretendard Variable\",Pretendard,-apple-system,\"Apple SD Gothic Neo\",\"Malgun Gothic\",sans-serif;\r\n  font-size:16px; line-height:1.72; letter-spacing:-.01em;\r\n  -webkit-font-smoothing:antialiased;\r\n}\r\n.page{ max-width:920px; margin:0 auto; padding:40px 22px 96px; }\r\n.doc{\r\n  background:var(--card); border:1px solid var(--line); border-radius:var(--radius);\r\n  box-shadow:var(--shadow-md); padding:clamp(26px,5vw,60px);\r\n}\r\n\r\n/* ============ COVER ============ */\r\n.cover{ background:var(--navy-bg); border:1px solid var(--navy-bd); border-radius:16px;\r\n  padding:30px 32px 28px; margin:0 0 12px; }\r\n.eyebrow{ font-size:12.5px; font-weight:700; letter-spacing:.14em; text-transform:uppercase;\r\n  color:var(--navy); margin-bottom:18px; }\r\n.cover h1{ font-size:clamp(30px,5.4vw,46px); line-height:1.12; font-weight:800;\r\n  color:var(--navy); margin:0 0 6px; letter-spacing:-.022em; }\r\n.cover-sub{ font-size:clamp(15px,2.4vw,19px); font-weight:700; color:var(--navy);\r\n  margin-bottom:16px; letter-spacing:-.01em; }\r\n.cover-lede{ font-size:clamp(14.5px,2.2vw,17px); color:var(--muted); font-weight:500;\r\n  margin:0 0 24px; max-width:54ch; }\r\n\r\n/* pastel meta cells (blue / pink / purple / yellow) */\r\n.cover-meta{ display:grid; grid-template-columns:repeat(4,1fr); gap:8px;\r\n  background:#fff; border:1px solid var(--navy-bd); border-radius:12px; padding:8px; }\r\n.cm{ border-radius:14px; padding:14px 16px; display:flex; flex-direction:column; gap:4px;\r\n  border:1px solid transparent; }\r\n.cm-k{ font-size:11px; font-weight:800; letter-spacing:.06em; text-transform:uppercase; opacity:.85; }\r\n.cm-v{ font-size:14.5px; font-weight:800; letter-spacing:-.01em; }\r\n.cm:nth-child(4n+1){ background:var(--sky-bg);    border-color:var(--sky-bd);    color:var(--sky-dp); }\r\n.cm:nth-child(4n+2){ background:var(--orange-bg); border-color:var(--orange-bd); color:var(--orange-dp); }\r\n.cm:nth-child(4n+3){ background:var(--violet-bg); border-color:var(--violet-bd); color:var(--violet-dp); }\r\n.cm:nth-child(4n+4){ background:var(--amber-bg);  border-color:var(--amber-bd);  color:var(--amber-dp); }\r\n.cm-k{ color:inherit; } .cm-v{ color:inherit; }\r\n\r\n.sync-badge{ display:inline-block; margin-top:18px; font-size:12px; font-weight:700;\r\n  color:var(--navy); background:#fff; border:1px solid var(--navy-bd);\r\n  padding:8px 14px; border-radius:10px; line-height:1.5; }\r\n\r\n/* ============ HEADINGS / TEXT ============ */\r\nh2{ font-size:clamp(20px,3vw,25px); font-weight:800; color:var(--navy);\r\n  letter-spacing:-.02em; line-height:1.25; margin:52px 0 16px; padding-top:24px;\r\n  border-top:1px solid var(--line); position:relative; }\r\nh2::before{ content:\"\"; position:absolute; top:-1px; left:0; width:54px; height:3px;\r\n  background:var(--navy); border-radius:3px; }\r\nh3{ font-size:17.5px; font-weight:800; color:var(--ink); letter-spacing:-.015em;\r\n  margin:28px 0 12px; line-height:1.3; }\r\np{ margin:0 0 13px; }\r\nstrong{ font-weight:700; color:var(--ink); }\r\nem{ font-style:normal; color:#586383; font-weight:500; }\r\ncode{ font-family:\"SFMono-Regular\",ui-monospace,Menlo,Consolas,monospace; font-size:.86em;\r\n  background:var(--accent-soft); color:var(--accent-ink); padding:.16em .5em; border-radius:6px;\r\n  font-weight:600; word-break:keep-all; }\r\n\r\n/* ============ DAY DIVIDER (strong anchor between colored cards) ============ */\r\n.day-divider{ display:flex; align-items:center; gap:14px; margin:48px 0 8px; padding-top:22px;\r\n  border-top:2px solid var(--navy); }\r\n.day-divider .d-badge{ flex:0 0 auto; font-size:12px; font-weight:800; letter-spacing:.06em;\r\n  color:var(--navy); background:var(--navy-bg); border:1px solid var(--navy-bd); padding:7px 13px; border-radius:9px; }\r\n.day-divider .d-title{ font-size:clamp(18px,2.6vw,22px); font-weight:800; color:var(--navy);\r\n  letter-spacing:-.02em; }\r\n\r\n/* ============ CARD (pastel families via local vars) ============ */\r\n.card{\r\n  --c-bg:#fff; --c-bg2:#F4F6FB; --c-bd:var(--line); --c-ac:var(--accent); --c-dp:var(--ink);\r\n  position:relative; background:var(--c-bg); border:1px solid var(--c-bd);\r\n  border-radius:var(--radius); padding:24px 26px 22px; margin:18px 0;\r\n  box-shadow:var(--shadow-md); overflow:visible;\r\n}\r\n.card::before{ content:\"\"; position:absolute; top:0; left:0; right:0; height:4px; background:var(--c-ac); border-radius:var(--radius) var(--radius) 0 0; }\r\n.card--sky   { --c-bg:var(--sky-bg);    --c-bg2:var(--sky-bg2);    --c-bd:var(--sky-bd);    --c-ac:var(--sky-ac);    --c-dp:var(--sky-dp); }\r\n.card--orange{ --c-bg:var(--orange-bg); --c-bg2:var(--orange-bg2); --c-bd:var(--orange-bd); --c-ac:var(--orange-ac); --c-dp:var(--orange-dp); }\r\n.card--violet{ --c-bg:var(--violet-bg); --c-bg2:var(--violet-bg2); --c-bd:var(--violet-bd); --c-ac:var(--violet-ac); --c-dp:var(--violet-dp); }\r\n.card--amber { --c-bg:var(--amber-bg);  --c-bg2:var(--amber-bg2);  --c-bd:var(--amber-bd);  --c-ac:var(--amber-ac);  --c-dp:var(--amber-dp); }\r\n.card--mint  { --c-bg:var(--mint-bg);   --c-bg2:var(--mint-bg2);   --c-bd:var(--mint-bd);   --c-ac:var(--mint-ac);   --c-dp:var(--mint-dp); }\r\n\r\n/* card header (badge + meta + title) */\r\n.sess-head{ display:flex; align-items:center; gap:10px; flex-wrap:wrap; margin:0 0 4px; }\r\n.sess-no{ font-size:12px; font-weight:800; letter-spacing:.08em; color:var(--c-dp);\r\n  background:rgba(255,255,255,.72); border:1px solid var(--c-bd); padding:4px 11px; border-radius:7px; }\r\n.sess-time{ font-size:13px; font-weight:700; color:var(--c-dp); opacity:.9; }\r\n.sess-title{ flex-basis:100%; font-size:19px; font-weight:800; color:var(--ink);\r\n  letter-spacing:-.015em; margin-top:6px; }\r\n\r\n/* meta strip (frosted white on tint) */\r\n.sess-meta{ font-size:13px; color:var(--text); background:rgba(255,255,255,.66);\r\n  border:1px solid var(--c-bd); border-radius:10px; padding:10px 14px; margin:10px 0 16px; line-height:1.55; }\r\n.sess-meta strong{ color:var(--c-dp); }\r\n.sess-meta em{ color:var(--text); font-weight:600; }\r\n\r\n/* small section label */\r\n.block-label{ font-size:12px; font-weight:800; letter-spacing:.04em; color:var(--c-dp);\r\n  margin:20px 0 8px; display:flex; align-items:center; gap:7px; }\r\n.block-label::before{ content:\"\"; width:7px; height:7px; border-radius:2px; background:var(--c-ac); }\r\n\r\n/* module head = white inset sub-card on the tint */\r\n.module-head{ background:#fff; border:1px solid var(--c-bd); border-left:3px solid var(--c-ac);\r\n  border-radius:10px; padding:10px 14px; margin:16px 0 8px; box-shadow:var(--shadow-sm); }\r\n.module-head strong{ font-size:15px; color:var(--ink); letter-spacing:-.01em; }\r\n.module-head em{ color:var(--muted); font-weight:500; }\r\n\r\n/* ============ LISTS ============ */\r\nul,ol{ margin:6px 0 16px; padding-left:0; list-style:none; }\r\nli{ position:relative; padding-left:22px; margin:7px 0; line-height:1.66; }\r\nul > li::before{ content:\"\"; position:absolute; left:4px; top:.66em; width:6px; height:6px;\r\n  border-radius:50%; background:var(--c-ac,var(--accent)); }\r\nol{ counter-reset:li; }\r\nol > li{ padding-left:30px; counter-increment:li; }\r\nol > li::before{ content:counter(li); position:absolute; left:0; top:.05em; width:21px; height:21px;\r\n  background:var(--c-ac,var(--accent)); color:#fff; border-radius:50%; font-size:11px;\r\n  font-weight:800; display:flex; align-items:center; justify-content:center; }\r\nli ul{ margin:6px 0 4px; }\r\nli ul > li{ padding-left:20px; }\r\nli ul > li::before{ width:5px; height:5px; background:var(--faint); top:.62em; }\r\n\r\n/* checklist */\r\nul > li.check{ padding-left:28px; margin:6px 0; }\r\nul > li.check::before{ content:\"\"; left:1px; top:.28em; width:14px; height:14px; border-radius:4px;\r\n  border:1.8px solid var(--c-ac,var(--accent)); background:rgba(255,255,255,.7); }\r\n\r\n/* ============ TABLES (white container, tinted header) ============ */\r\n.tbl-wrap{ overflow-x:auto; margin:14px 0 18px; border:1px solid var(--c-bd,var(--line));\r\n  border-radius:12px; background:#fff; box-shadow:var(--shadow-sm); }\r\ntable{ width:100%; min-width:520px; border-collapse:collapse; font-size:14px; background:#fff; }\r\nthead th{ background:var(--c-bg2,#F4F6FB); color:var(--c-dp,var(--ink)); font-weight:800;\r\n  text-align:left; font-size:12.5px; padding:11px 14px; border-bottom:1px solid var(--c-bd,var(--line)); white-space:nowrap; }\r\ntbody td{ padding:11px 14px; border-bottom:1px solid var(--line2); vertical-align:top;\r\n  line-height:1.6; color:var(--text); }\r\ntbody tr:last-child td{ border-bottom:0; }\r\ntbody td:first-child{ font-weight:700; color:var(--ink); }\r\n\r\n/* ============ CALLOUTS (pastel + icon chip) ============ */\r\n.callout{ display:flex; gap:11px; align-items:flex-start; margin:14px 0; padding:13px 16px;\r\n  border-radius:12px; font-size:14.5px; line-height:1.6; border:1px solid transparent; }\r\n.callout .ico{ flex:0 0 auto; width:22px; height:22px; border-radius:7px; color:#fff;\r\n  font-size:13px; font-weight:900; display:flex; align-items:center; justify-content:center; margin-top:1px; }\r\n.callout strong{ color:inherit; }\r\n.callout.info{ background:var(--sky-bg);   border-color:var(--sky-bd);   color:var(--sky-dp); }\r\n.callout.info .ico{ background:var(--sky-ac); }\r\n.callout.tip{  background:var(--amber-bg);  border-color:var(--amber-bd);  color:var(--amber-dp); }\r\n.callout.tip .ico{ background:var(--amber-ac); }\r\n.callout.ok{   background:var(--mint-bg);   border-color:var(--mint-bd);   color:var(--mint-dp); }\r\n.callout.ok .ico{ background:var(--mint-ac); }\r\n.callout.note{ background:var(--violet-bg); border-color:var(--violet-bd); color:var(--violet-dp); }\r\n.callout.note .ico{ background:var(--violet-ac); }\r\n.callout.warn{ background:var(--peach-bg);  border-color:var(--peach-bd);  color:var(--peach-dp); }\r\n.callout.warn .ico{ background:var(--peach-ac); }\r\n\r\n/* quote / pain-point */\r\nblockquote{ margin:14px 0; padding:13px 17px; background:rgba(255,255,255,.6);\r\n  border-left:3px solid var(--c-ac,var(--accent)); border-radius:0 10px 10px 0; color:var(--text); }\r\nblockquote p{ margin:0; font-weight:600; }\r\nblockquote p em{ color:var(--muted); }\r\n\r\n/* ============ MISC ============ */\r\nhr{ border:0; height:1px; background:transparent; margin:26px 0; }\r\n.footer-note, .doc > p:last-child em{ display:block; margin-top:28px; padding-top:18px;\r\n  border-top:1px solid var(--line); color:var(--faint); font-size:13px; font-weight:500; }\r\n\r\n/* ============ RESPONSIVE ============ */\r\n@media (max-width:680px){\r\n  .page{ padding:16px 12px 60px; }\r\n  .cover-meta{ grid-template-columns:repeat(2,1fr); }\r\n  .card{ padding:20px 18px; }\r\n}\r\n\r\n/* ============ PRINT ============ */\r\n@media print{\r\n  body{ background:#fff; }\r\n  .page{ padding:0; max-width:none; }\r\n  .doc{ border:0; box-shadow:none; border-radius:0; padding:0; }\r\n  .card,.tbl-wrap,table,.module-head,blockquote,.callout{\r\n    break-inside:avoid; box-shadow:none; -webkit-print-color-adjust:exact; print-color-adjust:exact; }\r\n  h2,h3,.day-divider{ break-after:avoid; }\r\n}\r\n\r\n/* ===== generic-document helpers ===== */\r\n.card h3{ color:var(--c-dp); margin:18px 0 10px; font-size:16px; }\r\n.cover-lede:last-child{ margin-bottom:0; }\r\n.callout .cbody{ flex:1; min-width:0; }\r\n.callout .cbody > :first-child{ margin-top:0; }\r\n.callout .cbody p{ margin:0 0 6px; }\r\n.callout .cbody p:last-child{ margin:0; }\r\n.callout .cbody ul,.callout .cbody ol{ margin:6px 0; }\r\n.callout .cbody strong{ color:inherit; }\r\n/* intro prose between cover and first card */\r\n.intro{ margin:4px 0 6px; }\r\n</style><style>\r\n/* v1.1 screen-readability override */\r\n@media screen{\r\n  .page{ max-width:900px !important; margin:0 auto !important; padding-left:28px !important; padding-right:28px !important; box-sizing:border-box; }\r\n}\r\n</style></head><body><div class='page'><div class='doc'><header class=\"cover\"><div class=\"eyebrow\">선명리서치쎈터 · 내부 배포용</div><h1>알뜰폰의 다음 10년 — 1,000만 회선 이후의 생존 전략</h1><p class=\"cover-lede\"><strong>부제: 한국 MVNO 시장의 성숙, 참가자, 소비자, 그리고 독립계의 생존 조건</strong></p></header><div class=\"intro\"><p>저자: 공인회계사 이준수</p>\r\n<hr /></div><section class=\"card card--sky\"><div class=\"sess-head\"><span class=\"sess-no\">01</span><div class=\"sess-title\">판권지</div></div>\r\n<ul>\r\n<li>서명: 알뜰폰의 다음 10년 — 1,000만 회선 이후의 생존 전략</li>\r\n<li>저자: 공인회계사 이준수</li>\r\n<li>발행처: 선명리서치쎈터</li>\r\n<li>© 2026 선명리서치쎈터</li>\r\n<li>발행 형태: 내부·제한 배포용 전자책 (EPUB·PDF) — 서점 유통 없음, ISBN 미부여</li>\r\n<li>초판 원고 작성: 2026년 7월</li>\r\n<li>데이터 기준 시점: 2025년 1월 ~ 2026년 7월 (각 수치에 기준연월·출처 병기)</li>\r\n</ul>\r\n<blockquote>\r\n<p><strong>면책 고지</strong></p>\r\n<p>본서는 정보 제공 목적으로 작성된 시장 분석 자료이며, 특정 기업 또는 특정 종목에 대한 투자 권유·매수/매도 추천이 아닙니다. 본서에 수록된 수치는 공개 자료(정부 통계, 감사보고서, 언론 보도, 공개 조사) 기준이며, 일부 추정치는 산출 방법을 본문과 부록에 명시했습니다. 본서의 전망·시나리오는 작성 시점의 공개 정보에 기반한 자체 판단으로, 실제 결과와 다를 수 있습니다. 본서는 내부·제한 배포용으로, 발행처의 사전 동의 없는 외부 유통·인용을 금합니다.</p>\r\n</blockquote>\r\n<hr />\r\n</section><section class=\"card card--orange\"><div class=\"sess-head\"><span class=\"sess-no\">02</span><div class=\"sess-title\">서문</div></div>\r\n<p>2025년 6월, 한국 알뜰폰은 휴대폰 회선 기준 1,011만을 기록하며 사상 처음 1,000만 고지를 넘었다. 그리고 정확히 열 달 뒤인 2026년 4월, 이 시장은 통계 작성 이래 처음으로 두 달 연속 가입자 순유출을 겪는다. 정점과 변곡점 사이의 거리가 이렇게 짧았던 산업은 흔치 않다.</p>\r\n<p>이 책은 그 변곡점 위에서 쓰였다. 국내 알뜰폰(MVNO) 시장을 산업 구조 → 경쟁 참가자 → 소비자 → 미래 트렌드의 순서로 해부하고, 마지막으로 독립계 사업자 프리티/프리텔레콤을 사례로 \"1,000만 회선 이후\"를 살아남는 조건을 구체화한다.</p>\r\n<p>집필 과정에서 우리는 하나의 원칙을 지켰다. <strong>모든 수치는 공개 데이터로 교차 검증한다.</strong> 조사 과정에서 참고한 일부 비공개 자료의 수치가 공개 감사보고서와 불일치하는 사례가 발견되었고, 본서는 해당 수치를 전량 공개 데이터 기준으로 정정해 수록했다(정정 이력은 부록 C 참조). 통신업이 낯선 독자를 위해 전문용어는 첫 등장 시 풀어 쓰고, 부록 A에 용어집을 따로 두었다.</p>\r\n<p>이 책의 결론을 한 문장으로 압축하면 이렇다. <strong>\"알뜰폰의 다음 10년은 더 많이 얻는 자가 아니라, 덜 잃는 자의 시간이다.\"</strong> 그 근거를 지금부터 펼친다.</p>\r\n<p>본서는 정보 제공 목적으로 작성되었으며, 특정 기업 또는 특정 종목에 대한 투자 권유가 아닙니다.</p>\r\n<p>2026년 7월\r\n선명리서치쎈터 · 공인회계사 이준수</p>\r\n<hr />\r\n</section><section class=\"card card--violet\"><div class=\"sess-head\"><span class=\"sess-no\">03</span><div class=\"sess-title\">목차</div></div>\r\n<ul>\r\n<li>프롤로그 — 1,011만 번째 회선</li>\r\n<li><strong>1부 시장 — 성숙기의 문턱에 선 산업</strong></li>\r\n<li>1장 알뜰폰이란 무엇인가</li>\r\n<li>2장 1,000만 회선의 명과 암</li>\r\n<li>3장 다섯 개의 힘 — 산업 매력도 진단</li>\r\n<li>4장 가치는 어디서 새는가 — 밸류체인</li>\r\n<li>5장 규제가 시장을 만든다</li>\r\n<li>6장 살아남는 자의 조건 — 7가지 핵심 성공 요인</li>\r\n<li><strong>2부 참가자들 — 네 개의 진영</strong></li>\r\n<li>7장 경쟁 지형도</li>\r\n<li>8장 여섯 개의 얼굴 — 핵심 사업자 프로파일</li>\r\n<li>9장 전략 그룹과 비어 있는 자리</li>\r\n<li><strong>3부 소비자 — 요금제 유목민의 시대</strong></li>\r\n<li>10장 누가 알뜰폰을 쓰는가</li>\r\n<li>11장 세 명의 소비자</li>\r\n<li>12장 모요에서 시작해 모요로 끝난다 — 구매 여정</li>\r\n<li>13장 만족도 순위의 진실</li>\r\n<li>14장 소비자가 진짜 원하는 것 — JTBD</li>\r\n<li><strong>4부 미래 — 트렌드와 시나리오</strong></li>\r\n<li>15장 여섯 가지 힘의 이동</li>\r\n<li>16장 기술은 어디까지 왔나</li>\r\n<li>17장 세 갈래 길 — 2028년까지의 시나리오</li>\r\n<li><strong>5부 생존 전략 — 프리티/프리텔레콤 사례 연구</strong></li>\r\n<li>18장 국내 유일 3사망 사업자의 초상</li>\r\n<li>19장 일곱 가지 생존 조건</li>\r\n<li>20장 3단계 생존 로드맵</li>\r\n<li>21장 조기 경보와 컨틴전시</li>\r\n<li>에필로그 — 덜 잃는 자가 이기는 시장</li>\r\n<li>부록 A 용어집</li>\r\n<li>부록 B 데이터 출처 목록</li>\r\n<li>부록 C 데이터 한계와 정정 이력</li>\r\n</ul>\r\n<hr />\r\n</section><div class=\"day-divider\"><span class=\"d-badge\">프롤로그</span><span class=\"d-title\">1,011만 번째 회선</span></div><div class=\"intro\"><p>2025년 6월 말, 과학기술정보통신부 무선통신서비스 가입 현황 통계에 하나의 숫자가 찍혔다. 알뜰폰 휴대폰(고객용) <strong>1,011만 684회선</strong>. 사물인터넷(IoT) 회선을 제외한 순수 휴대폰 기준으로 알뜰폰이 1,000만을 넘은 것은 제도 도입 이래 처음이었다. 전체 이동통신 휴대폰 회선 5,730만 가운데 17.64% — 국민 다섯 명 중 한 명 가까이가 이동통신 3사가 아닌 알뜰폰으로 전화를 쓰고 있다는 뜻이다.</p>\r\n<p>축포는 오래가지 않았다. 2025년 7월 22일, 이동통신 단말기 보조금을 규제하던 단통법(이동통신단말장치 유통구조 개선에 관한 법률)이 폐지됐다. 보조금 경쟁이 부활하자 \"보조금을 많이 주면 이동통신사로 옮기겠다\"는 알뜰폰 이용자가 교체 예정자의 48%에 달했고(더스쿠프, 2026년 5월), 2026년 4월 -7,353명, 5월 -11,211명 — 알뜰폰 가입자는 두 달 연속 순유출로 돌아섰다(아주경제, 2026년 6월).</p>\r\n<p>정점에서 변곡점까지 열 달. 이 책은 이 열 달이 일시적 충격이 아니라 <strong>시장의 국면 전환</strong>이라는 진단에서 출발한다. 성장기의 문법 — 더 싸게, 더 많이, 더 빨리 — 은 이제 작동하지 않는다. 성숙기의 시장에서는 다른 질문이 필요하다. 이 시장의 구조는 누구에게 이익을 허락하는가(1부). 누가 남고 누가 떠나는가(2부). 소비자는 무엇에 움직이는가(3부). 다음 3년을 결정할 힘은 무엇인가(4부). 그리고 자본도 모회사도 없는 독립계 사업자는 무엇으로 살아남는가(5부).</p>\r\n<p>숫자와 사례는 많지만, 관통하는 이야기는 하나다. 1,011만 번째 회선이 개통되던 그 달, 한국 알뜰폰 산업은 이미 다른 시대에 들어서 있었다.</p>\r\n<hr /></div><div class=\"day-divider\"><span class=\"d-badge\">1부 시장</span><span class=\"d-title\">성숙기의 문턱에 선 산업</span></div><div class=\"intro\"><blockquote>\r\n<p>1부는 알뜰폰 산업의 뼈대를 다룬다. 이 산업이 무엇이고(1장), 얼마나 크며(2장), 왜 구조적으로 이익이 박한지(3~4장), 규제가 어떻게 시장의 모양을 결정하는지(5장), 그래서 살아남으려면 무엇이 필요한지(6장)까지 — 뒤에 나올 모든 논의의 좌표계다.</p>\r\n</blockquote></div><section class=\"card card--amber\"><div class=\"sess-head\"><span class=\"sess-no\">04</span><div class=\"sess-title\">1장 알뜰폰이란 무엇인가</div></div>\r\n<p><strong>이 장의 핵심: 알뜰폰은 '망 없는 통신사'다. 망을 빌려 쓰는 임차 사업이라는 태생적 구조가 이 산업의 거의 모든 것을 설명한다.</strong></p>\r\n<h3>망을 빌려 파는 사업</h3>\r\n<p>알뜰폰의 공식 명칭은 <strong>MVNO(Mobile Virtual Network Operator, 가상이동통신망사업자)</strong>다. 주파수와 무선망을 직접 보유하지 않고, 기간통신사업자 — 흔히 <strong>MNO(Mobile Network Operator)</strong>라 부르는 SKT·KT·LG유플러스 3사 — 의 이동통신망을 <strong>도매로 임차</strong>해 자체 브랜드와 요금제로 재판매하는 사업이다. 전기통신사업법상 \"이동통신 재판매\" 사업으로, 허가제가 아닌 등록제다. 건물주(MNO)에게 층을 빌려 자기 간판을 걸고 장사하는 임차 상인(MVNO)의 구조라고 생각하면 이해가 빠르다.</p>\r\n<p>임차의 깊이에 따라 사업 방식은 스펙트럼을 이룬다.</p>\r\n<ol>\r\n<li><strong>단순 재판매</strong>: 망·전산 모두 빌려 쓰고 요금제만 얹는 방식. 진입은 쉽지만 차별화 여지가 거의 없다.</li>\r\n<li><strong>부분 자체설비</strong>: 요금 청구(빌링), 고객관리, 가입자 정보 관리(HLR) 일부를 자체 구축. 상품 설계의 유연성이 생긴다.</li>\r\n<li><strong>풀MVNO</strong>: 핵심망 일부까지 자체 구축해 도매 종속에서 부분적으로 벗어난 형태. 국내에는 아직 출현하지 않았으며, 정부가 2025년 1월 도매대가 인하 시 \"풀MVNO 출현 지원\"을 명시적 정책 목표로 제시한 상태다(디지털데일리, 2025년 1월).</li>\r\n</ol>\r\n<h3>시장을 읽는 세 개의 분류 축</h3>\r\n<div class=\"tbl-wrap\"><table>\r\n<thead>\r\n<tr>\r\n<th>분류 축</th>\r\n<th>구분</th>\r\n<th>왜 중요한가</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>회선 유형</td>\r\n<td><strong>휴대폰(고객용) 회선</strong> vs <strong>IoT/M2M 회선</strong>(커넥티드카·원격관제 등)</td>\r\n<td>통계와 규제의 핵심 쟁점. IoT 포함 여부에 따라 점유율 수치가 달라진다(2장)</td>\r\n</tr>\r\n<tr>\r\n<td>사업자 유형</td>\r\n<td>① 이통 3사 자회사(SK텔링크, KT엠모바일, KT스카이라이프, LG헬로비전, 미디어로그) ② 대기업·금융권 계열(KB리브모바일, 토스모바일, 우리WON모바일 등) ③ 독립계 중소(프리티, 큰사람커넥트, 아이즈비전 등 다수)</td>\r\n<td>등록 사업자는 수십 개(공공데이터포털, 2026년 3월 기준). 유형에 따라 원가·규제·전략이 전혀 다르다(2부)</td>\r\n</tr>\r\n<tr>\r\n<td>선·후불</td>\r\n<td>선불(외국인·단기 체류 중심) vs 후불(주력)</td>\r\n<td>선불은 별도의 유통·CS 노하우가 필요한 니치 시장</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<h3>성장기의 끝, 성숙기의 문턱</h3>\r\n<p>산업 생명주기 관점에서 한국 알뜰폰은 <strong>성장기 말~성숙기 진입 구간, 2026년 변곡점 통과 중</strong>으로 판단된다. 근거는 네 가지다.</p>\r\n<p>첫째, <strong>가입자 성장이 정점을 지났다.</strong> 2025년 6월 1,011만 회선으로 정점을 찍은 뒤, 2026년 4~5월 두 달 연속 순유출로 전환했다. 2026년 1분기 순증(5만 706명)도 전년 동기(10만 6,423명)의 절반에 그쳤다(아주경제, 2026년 6월).</p>\r\n<p>둘째, <strong>점유율 상승세가 둔화됐다.</strong> 휴대폰 시장 내 알뜰폰 비중은 2021년 3분기 10.8%에서 2025년 3분기 17.9%까지 매년 올랐지만(뉴스토마토), 단통법 폐지 이후 상승 동력이 꺾였다.</p>\r\n<p>셋째, <strong>양적 성장이 질적 성장으로 이어지지 못했다.</strong> 전체 회선 기준 가입자 점유율은 20.0%인데 <strong>소매 매출액 점유율은 8.4%</strong>에 불과하다(2024년, KISDI 통신시장 경쟁상황평가 인용 보도). 가입자당 월평균 매출, 즉 <strong>ARPU(Average Revenue Per User)</strong>가 낮은 구조 탓이다.</p>\r\n<p>넷째, <strong>구조조정 신호가 켜졌다.</strong> '0원 요금제' 출혈경쟁의 후유증으로 중소 사업자 상당수가 영업적자 상태다. 과기정통부가 2026년 6월 전파사용료 감면 확대의 근거로 이를 공식 언급했을 정도다(전자신문, 2026년 6월). 성숙기 진입 시 나타나는 전형적인 통폐합 압력이다.</p>\r\n<p>다만 정부의 도매대가 대폭 인하(2025년 1월)와 전파사용료 90% 감면(2027년 시행 예정) 같은 정책 지원이 성숙기 진입을 지연시키는 반대 방향의 힘으로 작용하고 있다. 요약하면 한국 알뜰폰은 <strong>\"정책 의존형 성숙기 초입\"</strong> 산업이다.</p>\r\n</section><section class=\"card card--mint\"><div class=\"sess-head\"><span class=\"sess-no\">05</span><div class=\"sess-title\">2장 1,000만 회선의 명과 암</div></div>\r\n<p><strong>이 장의 핵심: 시장의 겉모습(회선 1,011만, 점유율 17.9%)과 속살(연 매출 약 2조 원, 매출 점유율 8.4%)의 격차가 이 산업의 본질이다.</strong></p>\r\n<h3>핵심 통계 한눈에 보기</h3>\r\n<div class=\"tbl-wrap\"><table>\r\n<thead>\r\n<tr>\r\n<th>지표</th>\r\n<th>수치</th>\r\n<th>기준연월</th>\r\n<th>출처</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>이동통신 전체 휴대폰 회선(3사+알뜰폰)</td>\r\n<td>5,730만 3,514회선</td>\r\n<td>2025.6말</td>\r\n<td>과기정통부 통계 인용 보도(ZDNet)</td>\r\n</tr>\r\n<tr>\r\n<td>알뜰폰 휴대폰(고객용) 회선</td>\r\n<td><strong>1,011만 684회선</strong> (첫 1,000만 돌파)</td>\r\n<td>2025.6말</td>\r\n<td>상동</td>\r\n</tr>\r\n<tr>\r\n<td>알뜰폰 휴대폰 회선 비중</td>\r\n<td>17.64% (2025년 3분기 17.9%)</td>\r\n<td>2025.6말</td>\r\n<td>디지털데일리·뉴스토마토</td>\r\n</tr>\r\n<tr>\r\n<td>기술방식 구성</td>\r\n<td>LTE 약 951만 / 5G 약 43만 (LTE 93% 편중)</td>\r\n<td>2025.6말</td>\r\n<td>ZDNet</td>\r\n</tr>\r\n<tr>\r\n<td>순증감</td>\r\n<td>2026년 4월 -7,353 / 5월 -11,211 (2개월 연속 순유출)</td>\r\n<td>2026.4~5</td>\r\n<td>아주경제</td>\r\n</tr>\r\n<tr>\r\n<td>알뜰폰 ARPU</td>\r\n<td>월 약 1만 6,000원 (MNO 3사 약 3만 6,000원의 44%)</td>\r\n<td>2023년</td>\r\n<td>KISDI 인용 보도</td>\r\n</tr>\r\n<tr>\r\n<td>소매 매출액 점유율</td>\r\n<td><strong>8.4%</strong> (가입자 점유율 20.0% 대비)</td>\r\n<td>2024년</td>\r\n<td>KISDI 인용 보도</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<h3>\"17.97%\"는 무엇을 세고 있는가 — IoT라는 착시</h3>\r\n<p>알뜰폰 점유율 통계를 볼 때는 <strong>무엇을 분모·분자에 넣었는지</strong>를 먼저 확인해야 한다. 규제 논의에서 쓰이는 '전체 회선' 기준 점유율에는 휴대폰 외에 IoT/M2M 회선이 포함되는데, 현대차·기아 등 완성차의 커넥티드카 회선이 국내 알뜰폰 회선의 40% 이상을 차지한다(경향신문 계열 보도, 2024년 11월). 이 IoT 물량이 통계를 부풀려, 이통 3사 자회사의 실질 점유율이 낮아 보이는 효과를 낸다. IoT를 제외한 휴대폰 기준으로 보면 <strong>이통 3사 자회사 5사의 점유율은 약 49%</strong>에 달한다(2024년 11월 보도 기준). 2023년부터 정부 통계는 IoT 회선을 알뜰폰 가입자 수와 분리 표기하기 시작했다.</p>\r\n<p>시중에 유통되는 \"알뜰폰 점유율 17.97%(2025년)\"류의 수치는 공개 통계(2025년 6월 말 17.64% → 3분기 17.9%)와 정합하는 <strong>휴대폰 회선 기준 수치</strong>로 확인된다. 즉 휴대폰 기준 \"약 18%\"는 신뢰할 수 있되, '전체 회선 20%'와 혼용하면 안 된다.</p>\r\n<h3>시장 규모: 연 약 2조 원 — 두 가지 방법의 교차 검증</h3>\r\n<p>공식 발표되는 '알뜰폰 소매시장 규모' 통계는 없다. 본서는 두 방법을 교차했다.</p>\r\n<p><strong>방법 A — 하향식(Top-Down)</strong>: 회선 수 × ARPU. 1,011만 회선 × 월 약 1만 6,000원 × 12개월 ≈ <strong>연 1.94조 원</strong>. ARPU 기준연도(2023년)와 회선 기준연월(2025년 6월)의 시차, 그리고 ARPU가 2020~2023년 연 15%가량 상승해 온 추세를 감안하면 <strong>1.9~2.2조 원 범위</strong>다.</p>\r\n<p><strong>방법 B — 상향식(Bottom-Up)</strong>: 주요 사업자 매출 합산. 감사보고서 기반 검증치인 KT엠모바일 3,455.8억 원(2024년)과 SK텔링크 알뜰폰 부문 1,446.9억 원(2024년)에, 미검증 참고치(미디어로그·큰사람커넥트·프리티 MVNO 부문)를 더하면 5개사 합계 약 0.97조 원. 여기에 LG헬로비전·KT스카이라이프·금융권·기타 60~70여 개 중소 사업자를 더한 전체 추정은 <strong>약 1.7~2.2조 원</strong>이다.</p>\r\n<blockquote>\r\n<p>조사 초기에 참고했던 한 비공개 자료의 경쟁사 매출 수치는 감사보고서와 대조한 결과 상당수가 불일치해 폐기했고, 위 수치는 전량 공개 데이터 기준 정정치다(부록 C). 정정 후에도 두 방법의 중첩 구간이 유지되므로, 본서는 <strong>국내 알뜰폰 소매시장 규모를 연 약 2.0조 원 내외(1.9~2.2조 원, 2025년 기준 추정)</strong>로 결론짓되, 1차 근거는 하향식 산출과 KISDI 매출 점유율 8.4%의 역산(이동통신 소매시장 전체 약 24조 원 내외)에 둔다.</p>\r\n</blockquote>\r\n<h3>3년 전망: 회선은 정체, 매출은 완만한 성장</h3>\r\n<p>전제는 네 가지다. ① 단통법 폐지로 2026년 회선 정체~순감 지속 ② 도매대가 최대 52% 인하(2025년 1월)로 원가 개선과 1만 원대 5G 20GB 요금제 확산 ③ 전파사용료 90% 감면(2027년 시행 예정)으로 중소사 비용 절감 ④ ARPU는 5G 요금제 비중 확대로 연 3~5% 완만 상승.</p>\r\n<div class=\"tbl-wrap\"><table>\r\n<thead>\r\n<tr>\r\n<th>항목</th>\r\n<th>2025(실적/추정)</th>\r\n<th>2026E</th>\r\n<th>2027E</th>\r\n<th>2028E</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>휴대폰 회선(만)</td>\r\n<td>1,011(6월 실측) → 연말 약 1,030</td>\r\n<td>1,000~1,040 (정체·소폭 순감)</td>\r\n<td>1,010~1,070 (정책효과 회복)</td>\r\n<td>1,030~1,100</td>\r\n</tr>\r\n<tr>\r\n<td>휴대폰 점유율</td>\r\n<td>17.6~17.9%</td>\r\n<td>17.3~18.0%</td>\r\n<td>17.5~18.5%</td>\r\n<td>17.5~19.0%</td>\r\n</tr>\r\n<tr>\r\n<td>소매시장 규모(조 원)</td>\r\n<td>2.0~2.2</td>\r\n<td>2.0~2.3</td>\r\n<td>2.1~2.5</td>\r\n<td>2.2~2.7</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<p>시장 성장률(CAGR, 2025→2028)은 <strong>매출 기준 연 3~6%</strong>(회선 0~2% + ARPU 3~5%)로 추정된다. 하방 리스크는 보조금 경쟁 재점화와 MNO 통합요금제·5G 중저가 확산, 상방 요인은 풀MVNO 출현과 IoT/B2B 신규 수요다. 자체 추정이므로 오차 가능성을 전제로 읽어야 한다.</p>\r\n<h3>참고: 글로벌 시장과의 온도차</h3>\r\n<p>2025년 글로벌 MVNO 시장 규모는 조사기관별 USD 890억~1,185억, 전망 성장률은 연 7.4~9.0%다(Grand View Research 외). 글로벌은 여전히 성장 산업이지만, 한국은 MNO 3사 과점 + 규제 주도형 시장으로 성장률과 수익 구조가 다르다. 직접 비교보다는 일본 IIJ, 미국 트랙폰 같은 풀MVNO 사업모델의 벤치마크 용도로 활용하는 편이 적절하다.</p>\r\n</section><section class=\"card card--sky\"><div class=\"sess-head\"><span class=\"sess-no\">06</span><div class=\"sess-title\">3장 다섯 개의 힘 — 산업 매력도 진단</div></div>\r\n<p><strong>이 장의 핵심: 다섯 개의 경쟁 압력 중 네 개가 '강함' 이상이다. 이 산업에서 이익은 차별화가 아니라 원가·규모·정책 수혜 자격에서 나온다.</strong></p>\r\n<p>산업의 구조적 수익성을 진단하는 고전적 도구인 포터의 5 Forces 분석 결과다. 강도는 1(약함)~5(매우 강함).</p>\r\n<div class=\"tbl-wrap\"><table>\r\n<thead>\r\n<tr>\r\n<th>힘(Force)</th>\r\n<th>강도</th>\r\n<th>핵심 분석</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td><strong>공급자(MNO) 교섭력</strong></td>\r\n<td><strong>5</strong></td>\r\n<td>망 조달을 3사에 100% 의존. 유일한 견제 장치인 도매대가 규제조차 그 원천이 시장이 아닌 정부다. 2025년 1월 데이터 도매대가 최대 52% 인하(SKT 1.29→0.62원/MB)도 정부 협상의 결과물. MNO는 자회사를 통해 도매·소매 양쪽에 참여하는 이해상충 구조</td>\r\n</tr>\r\n<tr>\r\n<td><strong>구매자 교섭력</strong></td>\r\n<td><strong>4</strong></td>\r\n<td>전환비용이 극히 낮다(번호이동 간소화, 자급제+eSIM, 무약정 관행). 모요 등 비교 플랫폼이 가격을 완전 투명화 → 0원 요금제 출혈경쟁 유발. 개별 협상력이 아니라 '언제든 떠날 수 있음'에 기반한 교섭력</td>\r\n</tr>\r\n<tr>\r\n<td><strong>신규 진입 위협</strong></td>\r\n<td>3</td>\r\n<td>등록제라 제도적 장벽은 낮고 금융권 등 이종 산업 진입이 이어지지만, 낮은 수익성이 실질적 진입 유인을 깎는다</td>\r\n</tr>\r\n<tr>\r\n<td><strong>대체재 위협</strong></td>\r\n<td><strong>4</strong></td>\r\n<td>MNO 온라인 다이렉트 요금제·5G 중저가·통합요금제가 가격 격차를 축소. 단통법 폐지로 보조금 경쟁까지 부활 → 2026년 4~5월 순유출로 위협이 현실화</td>\r\n</tr>\r\n<tr>\r\n<td><strong>기존 사업자 간 경쟁</strong></td>\r\n<td><strong>5</strong></td>\r\n<td>수십 개 사업자가 같은 망·비슷한 요금제로 가격 단일 축 경쟁. 자회사군(휴대폰 기준 약 49%)의 규모 우위 vs 중소사의 감면 혜택이라는 이중 구조 속 소모전 반복</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<p><strong>종합 판정: 5점 척도 평균 4.2 — 구조적 산업 매력도 낮음.</strong> 이 구조가 시사하는 바는 명확하다. 알뜰폰 시장에서 이익의 원천은 ① 규모의 경제 ② 원가(도매대가·전파사용료) 우위 ③ 정책 수혜 자격이며, 브랜드 프리미엄 같은 차별화의 여지는 제한적이다. 이 명제는 이후 모든 장의 전제가 된다.</p>\r\n</section><section class=\"card card--orange\"><div class=\"sess-head\"><span class=\"sess-no\">07</span><div class=\"sess-title\">4장 가치는 어디서 새는가 — 밸류체인</div></div>\r\n<p><strong>이 장의 핵심: 마진이 상류(MNO)와 하류(플랫폼·소비자 혜택)로 동시에 압착되는 '샌드위치 구조'다. 자체 전산을 가진 사업자만 탈출구가 있다.</strong></p>\r\n<pre><code>[MNO 망 도매] → [MVNE/자체 전산] → [MVNO 사업자] → [유통·판매 채널] → [소비자]\r\n SKT·KT·LGU+     빌링·HLR·전산       자회사/금융권/독립계   온라인 다이렉트·플랫폼   1,011만 회선\r\n</code></pre>\r\n<div class=\"tbl-wrap\"><table>\r\n<thead>\r\n<tr>\r\n<th>단계</th>\r\n<th>주요 플레이어</th>\r\n<th>경제성</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>① 망 도매(MNO)</td>\r\n<td>SKT(도매제공의무사업자), KT, LG유플러스</td>\r\n<td>도매 매출은 저마진이지만 한계비용이 낮아 실질 수익성 양호. 데이터 종량 도매대가 1.29→0.82원/MB(기본), SKT 선구매 결합 시 최대 0.62원/MB(2025년 1월)</td>\r\n</tr>\r\n<tr>\r\n<td>② MVNE/전산</td>\r\n<td>자체 구축(프리티·자회사군) vs 외부 임차(다수 중소사)</td>\r\n<td><strong>MVNE(Mobile Virtual Network Enabler)</strong>는 빌링·개통·고객관리 시스템을 제공하는 사업자·기능. 자체 전산 보유 시 상품 설계 유연성과 원가 우위 확보</td>\r\n</tr>\r\n<tr>\r\n<td>③ MVNO</td>\r\n<td>자회사 5사, 금융권 3사, 독립계 다수</td>\r\n<td><strong>영업이익률이 극히 얇다.</strong> 감사보고서 검증치 기준 업계 1위 KT엠모바일이 2.8%(2024년 매출 3,455.8억 원·영업이익 95.8억 원). 중소사 상당수는 적자. 업계 이익률은 대체로 0~3%의 박리 구조</td>\r\n</tr>\r\n<tr>\r\n<td>④ 유통</td>\r\n<td>비교 플랫폼(모요 등), 알뜰폰Hub, 우체국, 금융앱, 편의점 유심, 자사몰</td>\r\n<td>오프라인 대리점이 없어 저비용이나, 플랫폼 노출 경쟁·프로모션 비용이 신규 고객 획득 비용(<strong>CAC</strong>, Customer Acquisition Cost)의 핵심</td>\r\n</tr>\r\n<tr>\r\n<td>⑤ 소비자</td>\r\n<td>자급제·2030 온라인 가입자, 시니어, 외국인(선불), 취약계층</td>\r\n<td>ARPU 약 1.6만 원(2023년)으로 MNO의 44% 수준</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<p>구조적 특징을 한 문장으로 요약하면: <strong>가치의 원천(망)과 규제 레버(도매대가)가 모두 상류에 있고, 가격 결정력은 하류(비교 플랫폼과 소비자의 이탈 옵션)에 있다.</strong> 중간에 낀 MVNO의 마진은 양쪽에서 눌린다. 이 샌드위치에서 그나마 숨 쉴 공간을 만드는 것이 ② 단계의 자체 전산 내재화다 — 이 통찰은 5부의 사례 연구에서 결정적 역할을 한다.</p>\r\n</section><section class=\"card card--violet\"><div class=\"sess-head\"><span class=\"sess-no\">08</span><div class=\"sess-title\">5장 규제가 시장을 만든다</div></div>\r\n<p><strong>이 장의 핵심: 정부는 '알뜰폰 육성'(도매대가·전파사용료 지원)과 '유통 자유화'(단통법 폐지)라는 상충하는 두 정책을 동시에 구사하고 있다. 2025~2027년은 규제 순풍과 시장 역풍이 교차하는 구간이다.</strong></p>\r\n<p>알뜰폰만큼 규제가 손익계산서를 직접 좌우하는 산업은 드물다. 다섯 개의 핵심 규제 축을 정리한다.</p>\r\n<h3>① 도매대가 인하 — 10년 만의 최대 폭</h3>\r\n<p><strong>도매대가</strong>란 MVNO가 MNO에게 망 사용 대가로 지불하는 도매 요금이다. 2025년 1월, 데이터 종량 도매대가가 1.29원/MB에서 0.82원/MB로 기본 36% 인하됐고, SKT의 경우 연 5만TB 선구매 시 25% 추가 할인이 결합돼 <strong>최대 52% 인하(0.62원/MB)</strong>가 가능해졌다(ZDNet, 2025년 1월). 1만 원대 5G 20GB 요금제가 출시될 수 있었던 원가 기반이다. 단, 최대 인하율은 대량 선구매 커밋이 가능한 사업자에게만 열린다 — 물량이 곧 원가라는 뜻이다.</p>\r\n<h3>② 사전규제에서 사후규제로 — 원가 결정 메커니즘의 전환</h3>\r\n<p>종래에는 정부가 MVNO를 대신해 도매대가를 협상하는 <strong>사전규제</strong> 방식이었다. 이 제도가 2025년 3월 일몰되면서 MVNO가 MNO와 직접 협상하는 <strong>사후규제</strong>로 전환됐다. 전환 후 첫 자율협상(2025년 12월 개시, SKT 대 16개사)의 결과는 상징적이다 — 종량제(RM) 도매대가만 인하되고 수익배분(RS) 방식은 동결됐다(이뉴스투데이 외, 2026년). 정부 주도기(최대 52% 인하)와 비교하면 인하 폭·범위 모두 급감했다. 업계는 물론 과기정통부까지 사전규제 부활 필요 입장을 표명한 상태로, <strong>제도의 향방이 산업 수익성의 최대 단일 변수</strong>다.</p>\r\n<h3>③ 점유율 제한 입법 — 계류 중인 견제구</h3>\r\n<p>이통 3사 자회사와 대기업·금융권 계열의 합산 점유율을 60%로 제한하는 전기통신사업법 개정안(야당안 기준. 여당안은 자회사 50% + 사전규제 부활)이 2024년 12월 국회 과방위를 통과했으나 <strong>2025년 1월 이후 법사위 계류·교착 상태</strong>다. 성립 시 자회사 성장에 상한이 생겨 독립계에 공간이 열리지만, 60% 상한은 현 수준(자회사 약 49% + 금융권)과 비교해 여유가 있어 \"성립돼도 게임체인저는 아니다\"가 냉정한 판정이다.</p>\r\n<h3>④ 전파사용료 감면 — 중소사의 생명줄</h3>\r\n<p>중소 알뜰폰 사업자는 2012~2024년 전파사용료를 100% 면제받았고, 2025년 80%, 2026년 50%로 감면율이 줄어드는 일정이었다. 그런데 2026년 6월, 정부는 <strong>감면율을 50%에서 90%로 확대하고 3년 연장</strong>(2027년 시행 예정)을 발표했다(전자신문, 2026년 6월). 대기업·이통 자회사는 전액 부담을 유지한다. 규제가 만든 이 원가 격차 자체가 독립계의 핵심 경쟁 자원이다.</p>\r\n<h3>⑤ 단통법 폐지 — 알뜰폰 최대의 역풍</h3>\r\n<p>2025년 7월 22일 단통법 폐지로 지원금 상한·공시 의무가 사라지고 MNO 보조금 경쟁이 부활했다. 결과는 앞서 본 대로다: 교체 예정자 48%의 조건부 이탈 의향, 2026년 4~5월 실제 순유출. \"가계통신비 인하\"를 내건 알뜰폰 육성 정책과 정면으로 충돌하는 정책이 동시에 시행되고 있는 셈이다.</p>\r\n<p>이 밖에 금융권 진입 허용(2025년 4월 금융위가 알뜰폰을 은행 부수업무로 공식 승인 — 전 은행에 진입 문호 개방), 제4이통 주파수 할당 공고 요청 제도 신설 등이 경쟁 지형을 바꾸고 있다.</p>\r\n<p><strong>총평</strong>: 규제 순풍(원가 인하)과 시장 역풍(보조금 경쟁)이 교차하는 2025~2027년 구간은, <strong>중소 사업자 지위(감면 자격)를 가진 사업자에게 상대적으로 유리</strong>한 규제 구도다.</p>\r\n</section><section class=\"card card--amber\"><div class=\"sess-head\"><span class=\"sess-no\">09</span><div class=\"sess-title\">6장 살아남는 자의 조건 — 7가지 핵심 성공 요인</div></div>\r\n<p><strong>이 장의 핵심: 앞의 다섯 장을 종합하면 생존의 필요조건 일곱 가지가 도출된다. ①~④ 없이는 이익이 나지 않고, ⑤~⑦ 없이는 성장이 지속되지 않는다.</strong></p>\r\n<div class=\"tbl-wrap\"><table>\r\n<thead>\r\n<tr>\r\n<th>#</th>\r\n<th>핵심 성공 요인(KSF)</th>\r\n<th>근거</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>1</td>\r\n<td><strong>규모의 경제 — 가입자 임계 규모</strong></td>\r\n<td>영업이익률 0~3%의 박리 구조에서 전산·CS 고정비 흡수는 회선 수가 좌우한다. 매출 점유율 8.4% vs 가입자 점유율 20%의 갭은 규모 없이는 이익이 나지 않는 시장임을 보여준다</td>\r\n</tr>\r\n<tr>\r\n<td>2</td>\r\n<td><strong>자체 전산·빌링 시스템 내재화</strong></td>\r\n<td>외부 전산 임차 사업자는 상품 설계·원가 통제가 불가능하다(4장). 정부의 풀MVNO 육성 방향과도 정합</td>\r\n</tr>\r\n<tr>\r\n<td>3</td>\r\n<td><strong>도매 원가 우위 — 선구매 협상력 + 복수망 소싱</strong></td>\r\n<td>최대 52% 인하는 연 5만TB 선구매 조건부. 물량 커밋 능력이 원가를 가른다. 3사망 복수 소싱은 망별 대가 차익·상품 다양화 수단</td>\r\n</tr>\r\n<tr>\r\n<td>4</td>\r\n<td><strong>중소 사업자 지위 기반 정책 수혜 자격 유지</strong></td>\r\n<td>전파사용료 90% 감면·도매대가 보호는 중소사 한정(5장). 규제가 만든 원가 격차가 독립계의 핵심 경쟁 자원</td>\r\n</tr>\r\n<tr>\r\n<td>5</td>\r\n<td><strong>저비용 디지털 유통과 플랫폼 노출 경쟁력</strong></td>\r\n<td>가입의 주 경로가 비교 플랫폼·온라인으로 이동. 전환비용이 낮은 시장에서는 CAC 관리와 노출 순위가 성장 속도를 결정</td>\r\n</tr>\r\n<tr>\r\n<td>6</td>\r\n<td><strong>이탈 방어 — 리텐션 설계</strong></td>\r\n<td>이용자 48% 조건부 이탈 의향, 실제 순유출 국면. 결합 혜택·장기 할인·멤버십 등 잔존 유인이 없는 사업자부터 침식된다. <strong>리텐션(retention)</strong>은 기존 고객을 붙잡아 두는 유지 활동 전반을 뜻한다</td>\r\n</tr>\r\n<tr>\r\n<td>7</td>\r\n<td><strong>ARPU 다변화 — 5G 중용량·eSIM/로밍·IoT/B2B</strong></td>\r\n<td>ARPU가 정체되면 매출 성장은 회선 성장에 종속되는데, 회선은 정체 국면이다. 도매대가 인하로 열린 20~30GB 5G 구간과 B2B IoT가 단가 방어 경로</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<p>독립계 중소 사업자의 경우, ④(정책 수혜)와 ②(자체 전산)의 조합 없이는 자회사·금융권과의 소모전에서 구조적으로 열위라는 것이 1부의 결론이다. 이 일곱 가지는 2부에서 경쟁사 평가의 잣대로, 5부에서 생존 조건 진단의 뼈대로 다시 등장한다.</p>\r\n<hr />\r\n</section><div class=\"day-divider\"><span class=\"d-badge\">2부 참가자들</span><span class=\"d-title\">네 개의 진영</span></div><div class=\"intro\"><blockquote>\r\n<p>2부는 이 시장에서 싸우는 이들의 지도를 그린다. 자회사 과점과 롱테일 소모전이라는 이중 구조(7장), 대표 사업자 여섯의 속사정(8장), 그리고 전략 그룹 분석이 드러내는 '비어 있는 자리'(9장)까지 — 누가 남고 누가 떠날지를 가늠하는 부다.</p>\r\n</blockquote></div><section class=\"card card--mint\"><div class=\"sess-head\"><span class=\"sess-no\">10</span><div class=\"sess-title\">7장 경쟁 지형도</div></div>\r\n<p><strong>이 장의 핵심: 상위는 이통 3사 자회사가 과점하고, 나머지 절반을 50개 가까운 사업자가 나눠 갖는 '과점 + 롱테일' 구조. 파이가 줄어드는 국면에서 경쟁은 제로섬으로 바뀌었다.</strong></p>\r\n<h3>네 개의 진영과 하나의 그림자</h3>\r\n<p>국내 알뜰폰 시장의 참가자는 네 진영으로 나뉜다. 가입자 수치는 과기정통부 사업자별 통계 인용 자료(2024년 12월~2025년 4월 시점) 기준이다.</p>\r\n<ol>\r\n<li><strong>이통 3사 자회사 5사</strong> — KT엠모바일(170.4만), 미디어로그(103.7만), SK텔링크(77.7만), LG헬로비전(74.5만), KT스카이라이프(42.2만). 휴대폰 회선 기준 합산 <strong>약 47~49% 과점</strong>.</li>\r\n<li><strong>금융권</strong> — KB리브모바일(43.7만, 2025년 6월), 토스모바일(약 20만), 우리WON모바일(약 3만). 합계 약 66만으로 알뜰폰 휴대폰 회선의 <strong>약 6.5%</strong>. 규모는 아직 틈새지만, 2025년 4월 은행 부수업무 정식 승인으로 진입장벽이 사라진 상시 위협이다.</li>\r\n<li><strong>독립계</strong> — 유니컴즈(46.8만), 프리티 통합(약 56만), 큰사람커넥트(29.0만), 아이즈비전(22.7만) 등 수십 개사의 롱테일. 활동 사업자는 약 54개사(머니투데이, 2025년 3월).</li>\r\n<li><strong>IoT 특수</strong> — 현대차·기아(커넥티드카 회선), 에스원(보안 관제) 등. 소매 경쟁과는 분리된 B2B 영역.</li>\r\n</ol>\r\n<p>그리고 진영 바깥에 그림자처럼 드리운 <strong>간접 경쟁자</strong>가 있다. MNO 3사의 온라인 다이렉트 브랜드 — SKT '에어'(2025년 10월 출시), KT '요고', LG유플러스 '너겟' — 다. \"알뜰폰보다 비싸지만 매장 요금제보다 싼\" 시장 한가운데로 침투하며, 단통법 폐지 보조금과 함께 알뜰폰을 위(보조금)와 아래(다이렉트 요금제)에서 협공한다. 2026년 순유출의 구조적 원인이다.</p>\r\n<h3>시장 집중도</h3>\r\n<div class=\"tbl-wrap\"><table>\r\n<thead>\r\n<tr>\r\n<th>지표</th>\r\n<th>수치</th>\r\n<th>산출 근거</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>CR1(KT엠모바일)</td>\r\n<td>약 17%</td>\r\n<td>170.4만 / 1,011만</td>\r\n</tr>\r\n<tr>\r\n<td>CR3(KT엠+미디어로그+SK텔링크)</td>\r\n<td>약 35%</td>\r\n<td>상위 3사 합산</td>\r\n</tr>\r\n<tr>\r\n<td>CR5(자회사 4사+유니컴즈)</td>\r\n<td>약 47%</td>\r\n<td>상위 5사 합산</td>\r\n</tr>\r\n<tr>\r\n<td>자회사 5사 합산</td>\r\n<td>약 47~49%</td>\r\n<td>IoT 제외 기준 약 49%(2024년 11월)</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<p><strong>CR(Concentration Ratio)</strong>은 상위 N개사의 점유율 합계다. 판정은 \"중상위 집중\" — 상위는 자회사가 과점하되, 잔여 약 50%를 50개사 가까이가 나눠 갖는 극단적 롱테일이다. 형식상으로는 경쟁적 시장이지만 실질은 \"자회사 과점 + 나머지 소모전\"이다.</p>\r\n<h3>경쟁의 여섯 차원</h3>\r\n<p>이 시장의 경쟁은 여섯 축에서 벌어진다. ① 가격/데이터 단가(제1 차원 — 비교 플랫폼 정렬 경쟁) ② 원가 구조(선구매 협상력, 감면 자격) ③ 브랜드 신뢰·CS(2025년 SKT 해킹 사고 이후 보안·신뢰 가중치 상승) ④ 유통·플랫폼 노출 ⑤ 리텐션 설계 ⑥ 신사업 확장(eSIM·로밍·IoT/B2B). 가격 하나로 싸우는 사업자일수록 침식이 빠르다는 것이 이후 장들의 공통 발견이다.</p>\r\n</section><section class=\"card card--sky\"><div class=\"sess-head\"><span class=\"sess-no\">11</span><div class=\"sess-title\">8장 여섯 개의 얼굴 — 핵심 사업자 프로파일</div></div>\r\n<p><strong>이 장의 핵심: 외형 1위도 이익률 3% 미만, 자본력 있는 금융권도 누적 적자 — '규모도 자본도 이익을 보장하지 못하는 시장'이라는 사실이 여섯 개 프로파일에서 반복된다.</strong></p>\r\n<h3>KT엠모바일 — 규모의 제왕, 그러나 박리</h3>\r\n<p>가입자 170.4만(2024년 12월, 업계 최초 170만 달성). 2024년 매출 3,455.8억 원, 영업이익 95.8억 원 — 영업이익률 <strong>2.8%</strong>다. \"압도적 1등 알뜰폰\" 브랜딩과 KT그룹 전산·유통·AS 인프라, 대규모 선구매 협상력을 갖췄지만, 전파사용료 전액 부담과 점유율 제한 입법 리스크가 구조적 족쇄다. 규제 리스크 탓에 공격적 순증 드라이브를 걸기 어려운 국면 — 1위가 성장을 자제하는 구간이 독립계에는 기회가 된다.</p>\r\n<h3>SK텔링크(SK세븐모바일) — 흔들리는 2강</h3>\r\n<p>가입자 77.7만. 2024년 알뜰폰 부문 매출 1,446.9억 원으로 역성장했고, 구조조정 일회성 비용으로 이익이 급감했다(뉴스웨이, 2026년 6월). 결정타는 <strong>2025년 SKT 유심 해킹 사고</strong> — 모회사 망 신뢰의 훼손이 세븐모바일 가입에 그대로 전이됐다. 시니어·안정 추구층 특화와 국제전화(00700) 겸업이 버팀목이다.</p>\r\n<h3>미디어로그(U+유모바일) — 외형 2위, 수익성 최약체</h3>\r\n<p>가입자 103.7만으로 외형 2위지만 2024년 3년 만에 적자로 전환했고 손실 폭이 전년 대비 약 869% 확대됐다(머니투데이, 2025년 3월). 브랜드평판은 14위(2026년 6월)로 규모 대비 최약. LG유플러스의 알뜰폰 이원화 전략(미디어로그=온라인 저가 공격수, LG헬로비전=결합·지역 수비수)에서 공격수 역할을 맡아, <strong>모회사 의지에 따라 출혈 마케팅을 지속할 수 있는 자본 뒷배</strong>가 시장 전체에는 가장 큰 위협 요인이다.</p>\r\n<h3>KB리브모바일 — 자본은 크지만 성장은 멈췄다</h3>\r\n<p>가입자 43.7만(2025년 6월). 5년 연속 적자에 누적 적자 600억 원 이상, 2023년 40만 돌파 후 2년간 순증이 약 1만 명에 그쳤다(디지털포스트, 2026년). KB스타뱅킹 기반 크로스셀과 자본력에도 불구하고 금융 결합 할인만으로는 확장의 한계가 드러났다. 금융권 일반의 특성 — <strong>자본은 있으나 통신업 운영 역량과 헌신이 제한적</strong> — 을 보여주는 표본이다.</p>\r\n<h3>토스모바일 — UX는 최강, 가격은 비싸다</h3>\r\n<p>가입자 약 20만. 토스앱 개통 UX와 캐시백으로 화제성은 높지만 \"편리하지만 알뜰하진 않다\"(디지털데일리 사용기)는 평가처럼 가격 경쟁력 자체는 열위이고 수익성은 미검증이다. 다만 2030의 UX 기대 수준을 끌어올린 존재로, 모든 알뜰폰 앱·셀프서비스가 상대 비교당하는 기준점이 됐다.</p>\r\n<h3>아이즈비전(아이즈모바일) — 독립계의 동병상련</h3>\r\n<p>가입자 22.7만. 선불·외국인 특화 노하우와 전파사용료 감면 수혜에도 규모·자본 열위로 단독 생존 압박을 받는다. 독립계 통폐합 국면에서 잠재적 피인수·제휴 후보군(15~25만 규모대)의 전형이다.</p>\r\n<blockquote>\r\n<p><strong>재무 수치에 관한 편집자 주</strong>: 위 실적 수치는 감사보고서를 원천으로 하는 기업정보 플랫폼과 언론 보도로 교차 검증한 값이다. 조사 과정에서 참고한 일부 비공개 자료의 경쟁사 수익성 수치는 검증 결과 실제와 2배 이상 차이 나는 항목이 발견돼 전량 폐기했다(부록 C). 정정 후의 그림 — 업계 1위 2.8%, 2위권 역성장·적자, 금융권 누적 적자 — 은 오히려 \"박리 시장\" 판정을 강화한다.</p>\r\n</blockquote>\r\n</section><section class=\"card card--orange\"><div class=\"sess-head\"><span class=\"sess-no\">12</span><div class=\"sess-title\">9장 전략 그룹과 비어 있는 자리</div></div>\r\n<p><strong>이 장의 핵심: 전략 그룹 지도에서 '고신뢰 × 고가격경쟁력'의 우상단은 비어 있다. 자회사는 규제와 원가 탓에, 독립계는 신뢰 부족 탓에 도달하지 못한 자리다.</strong></p>\r\n<h3>여섯 개의 전략 그룹</h3>\r\n<div class=\"tbl-wrap\"><table>\r\n<thead>\r\n<tr>\r\n<th>전략 그룹</th>\r\n<th>구성원</th>\r\n<th>원가 지위</th>\r\n<th>현재 성과</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>A. MNO 자회사</td>\r\n<td>KT엠모바일, SK텔링크, LG헬로비전, 미디어로그, KT스카이라이프</td>\r\n<td>도매 내부거래 우위, 단 전파사용료 전액 부담</td>\r\n<td>외형 1위군이나 이익률 0~3%, 일부 적자</td>\r\n</tr>\r\n<tr>\r\n<td>B. 금융권</td>\r\n<td>KB리브, 토스, 우리WON</td>\r\n<td>원가 열위(위탁 전산)를 자본으로 보전</td>\r\n<td>전원 적자 추정, 성장 정체</td>\r\n</tr>\r\n<tr>\r\n<td>C. 독립계 대형</td>\r\n<td>프리티 통합, 유니컴즈, 한국케이블텔레콤, 큰사람커넥트</td>\r\n<td><strong>감면·도매 보호 — 구조적 원가 우위</strong></td>\r\n<td>소폭 흑자~손익분기</td>\r\n</tr>\r\n<tr>\r\n<td>D. 독립계 소형/선불 특화</td>\r\n<td>아이즈비전, 에넥스텔레콤, 스마텔 등 40여 사</td>\r\n<td>감면 수혜하나 규모 미달</td>\r\n<td>상당수 영업적자 — 통폐합 압력</td>\r\n</tr>\r\n<tr>\r\n<td>E. IoT 특수</td>\r\n<td>에스원, 현대차·기아</td>\r\n<td>대량 회선 단가</td>\r\n<td>소매 경쟁과 분리</td>\r\n</tr>\r\n<tr>\r\n<td>F. (간접) MNO 다이렉트</td>\r\n<td>에어·요고·너겟</td>\r\n<td>MNO 원가 그 자체</td>\r\n<td>알뜰폰 상단 수요 흡수 중</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<p>그룹 간 역학의 핵심은 <strong>D그룹의 붕괴</strong>다. 적자 누적으로 매물화가 진행 중이고, 그 가입자 자산은 A·C그룹으로 재배분될 전망이다. 자회사(A)는 점유율 규제 리스크로 인수에 소극적일 수밖에 없어, 인수 주체는 사실상 독립계 대형(C) 또는 신규 자본으로 좁혀진다. 한편 F그룹의 침투는 A~D 모든 그룹의 상단 고객을 깎는 공통 위협이다.</p>\r\n<h3>포지셔닝 맵이 드러내는 세 개의 공백</h3>\r\n<p>가로축을 가격 공격성, 세로축을 브랜드 신뢰·서비스 폭으로 놓고 참가자들을 배치하면 세 개의 화이트스페이스가 보인다.</p>\r\n<ol>\r\n<li><strong>\"믿을 수 있는 최저가\" — 우상단 공백</strong>: 고신뢰와 고가격경쟁력을 겸비한 자리는 비어 있다. 자회사는 원가(전파사용료 전액 부담)와 규제 탓에, 독립계 다수는 신뢰 부족 탓에 도달하지 못한다. 감면 원가 우위와 브랜드 평판을 동시에 가진 사업자만 노릴 수 있는 자리다.</li>\r\n<li><strong>\"망 선택권\"이라는 부재하는 축</strong>: 어떤 경쟁사도 복수의 통신망을 단일 브랜드로 제공하지 못한다. 자회사는 자사망에 종속되고, 금융권·독립계 대부분도 1~2개 망에 그친다. SKT 해킹 이후 소비자가 처음으로 '망 자체의 리스크'를 인식하기 시작한 지금, \"망을 갈아탈 수 있는 통신사\"는 지도에 없는 제3의 차별화 축이다.</li>\r\n<li><strong>시니어 오프라인 접점</strong>: SK세븐모바일·우체국 외에 시니어 대면 채널이 희소하다. 단, 투자 대비 효율은 검증이 필요하다(3부 참조).</li>\r\n</ol>\r\n<p>이 세 공백 중 앞의 두 개에 가장 근접한 사업자가 누구인지는 5부에서 자세히 다룬다.</p>\r\n<hr />\r\n</section><div class=\"day-divider\"><span class=\"d-badge\">3부 소비자</span><span class=\"d-title\">요금제 유목민의 시대</span></div><div class=\"intro\"><blockquote>\r\n<p>3부는 시장의 최종 심판자인 소비자를 들여다본다. 누가 쓰고(10장), 어떤 사람들이며(11장), 어떤 경로로 들어와 어떤 이유로 떠나는지(12장), 만족도·평판 순위를 어디까지 믿어야 하는지(13장), 그리고 그들이 아직 채우지 못한 욕구는 무엇인지(14장)를 다룬다. 2차 공개 데이터 기반 분석이며, 1차 조사(설문·FGI)는 미실시임을 밝혀 둔다.</p>\r\n</blockquote></div><section class=\"card card--violet\"><div class=\"sess-head\"><span class=\"sess-no\">13</span><div class=\"sess-title\">10장 누가 알뜰폰을 쓰는가</div></div>\r\n<p><strong>이 장의 핵심: 신규 유입은 2030에 극단적으로 편중되지만, 잔존 고객은 전 연령에 고르게 퍼져 있다. '획득 시장'과 '유지 시장'의 얼굴이 다르다는 것 — 이것이 알뜰폰 소비자 전략의 출발점이다.</strong></p>\r\n<h3>이용자 기초 구조</h3>\r\n<div class=\"tbl-wrap\"><table>\r\n<thead>\r\n<tr>\r\n<th>지표</th>\r\n<th>수치</th>\r\n<th>기준시점</th>\r\n<th>출처</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>연령 구성(이용자)</td>\r\n<td>20대 25% / 30대 24% / 40대 21% / 50대+ 25% / 10대 5%</td>\r\n<td>2024년</td>\r\n<td>컨슈머인사이트 인용 보도(한국경제)</td>\r\n</tr>\r\n<tr>\r\n<td>신규 가입 연령(플랫폼)</td>\r\n<td>20대 34.3% + 30대 35.6% = 약 70%</td>\r\n<td>2024년 4~5월 모요 신규 가입</td>\r\n<td>뉴스천지</td>\r\n</tr>\r\n<tr>\r\n<td>자급제 단말 비율</td>\r\n<td>신규 가입자의 87~90%</td>\r\n<td>2022~2024년</td>\r\n<td>정보통신신문, 디지털데일리</td>\r\n</tr>\r\n<tr>\r\n<td>ARPU</td>\r\n<td>월 약 1.6만 원(MNO의 44%)</td>\r\n<td>2023년</td>\r\n<td>KISDI 인용 보도</td>\r\n</tr>\r\n<tr>\r\n<td>이탈 리스크</td>\r\n<td>교체 예정자 48% \"보조금 많으면 이통사 이동\"</td>\r\n<td>2026년 5월</td>\r\n<td>더스쿠프</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<p><strong>자급제</strong>란 통신사 대리점이 아니라 가전 매장·온라인에서 단말기를 따로 사서 유심만 끼워 쓰는 방식이다. 신규 가입자의 약 9할이 자급제라는 사실은, 알뜰폰 유입 경로가 완전히 온라인·셀프 중심으로 재편됐음을 뜻한다.</p>\r\n<h3>다섯 개의 세그먼트</h3>\r\n<div class=\"tbl-wrap\"><table>\r\n<thead>\r\n<tr>\r\n<th>세그먼트</th>\r\n<th>규모 추정</th>\r\n<th>핵심 니즈</th>\r\n<th>매력도·우선순위</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>① 2030 실속형(자급제+온라인)</td>\r\n<td>약 490~500만(이용자의 49%)</td>\r\n<td>최저가 데이터 요금제, eSIM·빠른 개통, 앱/UX</td>\r\n<td><strong>1순위</strong> — 볼륨의 원천이나 이탈도 최다. CAC·리텐션 관리가 전제</td>\r\n</tr>\r\n<tr>\r\n<td>② 4050 가족 총무형</td>\r\n<td>약 210만+(가구 단위 배수 효과)</td>\r\n<td>복수 회선 관리 편의, 망 선택권(부모 세대의 망 선호), 청구서 통합</td>\r\n<td><strong>2순위</strong> — 다회선·장기 잔존으로 수익성 최고</td>\r\n</tr>\r\n<tr>\r\n<td>③ 시니어(60+)</td>\r\n<td>수백만 추정(세부 데이터 제한)</td>\r\n<td>전화 상담, 간단 요금제, 오프라인 접점</td>\r\n<td>3순위 — 이탈은 적으나 CS 역량 없이는 역효과</td>\r\n</tr>\r\n<tr>\r\n<td>④ 세컨드폰/듀얼심</td>\r\n<td>데이터 제한(eSIM 확산으로 증가세)</td>\r\n<td>eSIM 즉시 개통, 월 0~5천 원 유지비</td>\r\n<td>4순위 — 마진 낮지만 회선 방어·교차판매 기반</td>\r\n</tr>\r\n<tr>\r\n<td>⑤ 외국인·단기체류(선불)</td>\r\n<td>데이터 제한</td>\r\n<td>즉시 개통, 다국어 CS, 선불 충전 편의</td>\r\n<td>5순위 — 특수 채널 필요, 니치 연계 여지</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<p><strong>eSIM</strong>은 단말기에 내장된 디지털 유심으로, 실물 유심 배송 없이 즉시 개통이 가능하고 한 단말에 두 번호(듀얼심)를 쓸 수 있게 해 준다. ④ 세그먼트 성장의 기술적 토대다.</p>\r\n<p>시사점은 명확하다. 유입은 2030이 끌고(신규의 약 70%), 잔존은 전 연령에 분포한다(50대+ 25%). <strong>획득 전략은 2030 온라인에, 유지 전략은 4050·시니어까지 포괄해서</strong> 설계해야 한다.</p>\r\n</section><section class=\"card card--amber\"><div class=\"sess-head\"><span class=\"sess-no\">14</span><div class=\"sess-title\">11장 세 명의 소비자</div></div>\r\n<p><strong>이 장의 핵심: 알뜰폰의 실질 구매 결정자는 표면의 가입자와 다른 경우가 많다. 시니어 마케팅의 진짜 타깃은 시니어가 아니라 그들의 자녀다.</strong></p>\r\n<h3>페르소나 A — \"요금제 유목민\" 김세민(29, 직장 3년차, 서울)</h3>\r\n<p>자급제 갤럭시에 모요 알림을 켜 두고 0원·반값 프로모션을 추적한다. 원하는 것은 \"월 통신비 1만 원 이하, 약정 없는 상태 유지\". 셀프개통은 30분 안에 끝나야 하고, 고객센터에 전화할 일 자체를 만들기 싫어한다. 프로모션 종료 시점을 캘린더에 적어 두고 그날 떠난다. — 이 세그먼트는 볼륨을 만들지만 충성도는 없다. 여기서 이기는 방법은 브랜드가 아니라 <strong>플랫폼 노출 순위와 '프로모션 이후 요금의 착지점' 설계</strong>다.</p>\r\n<h3>페르소나 B — \"가족 통신 총무\" 박정훈(47, 자영업, 경기)</h3>\r\n<p>본인·아내·중학생 자녀·모친(SKT망 선호)의 4회선을 관리한다. 단통법 폐지 후 \"최신 폰 0원\" 광고에 흔들렸지만 가족 전체를 옮기는 건 번거롭다. 가격보다 \"문제 생겼을 때 전화가 되는가\"를 중시하고, 청구서 4장을 1장으로 만들고 싶어 한다. — <strong>복수 망을 한 브랜드에서 제공하는 사업자만이 이 사람의 문제를 풀 수 있다.</strong> 반대로 망별로 고객센터 번호가 다른 구조는 이 페르소나에게 치명적 감점이다.</p>\r\n<h3>페르소나 C — \"자녀가 바꿔준\" 이순자(68, 은퇴, 부산)</h3>\r\n<p>딸이 \"엄마 요금 3만 원은 사기\"라며 알뜰폰으로 바꿔 줬다. 본인은 통신사 이름도 정확히 모른다. 이탈 결정도 본인이 아니라 자녀가 한다. — 시니어 마케팅의 실제 수신자는 <strong>대리 결정자인 2040 자녀</strong>다. 콜센터 응대가 나쁘면 자녀들의 커뮤니티(맘카페 등)에서 평판이 깎이는 경로로 작동한다.</p>\r\n</section><section class=\"card card--mint\"><div class=\"sess-head\"><span class=\"sess-no\">15</span><div class=\"sess-title\">12장 모요에서 시작해 모요로 끝난다 — 구매 여정</div></div>\r\n<p><strong>이 장의 핵심: 알뜰폰 구매 여정은 비교 플랫폼에서 시작해 비교 플랫폼으로 돌아오는 루프다. 브랜드는 여정의 앞단을 통제하지 못하며, 차별화 기회는 개통·사용·이탈 방어의 뒷단에만 남아 있다.</strong></p>\r\n<div class=\"tbl-wrap\"><table>\r\n<thead>\r\n<tr>\r\n<th>단계</th>\r\n<th>인지</th>\r\n<th>고려</th>\r\n<th>구매(개통)</th>\r\n<th>사용</th>\r\n<th>추천/이탈</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>주요 접점</td>\r\n<td>모요·커뮤니티·유튜브 절약 콘텐츠·지인 구전, (시니어) 우체국</td>\r\n<td>모요 요금제 비교·리뷰, 0원 프로모션 목록</td>\r\n<td>셀프개통 — 유심 배송(1~3일) 또는 eSIM 즉시</td>\r\n<td>셀프서비스 앱, 고객센터, 자동납부</td>\r\n<td>프로모션 종료 알림, 커뮤니티 후기, 재비교</td>\r\n</tr>\r\n<tr>\r\n<td>고객 심리</td>\r\n<td>\"통신비가 아깝다\"</td>\r\n<td>\"어디가 제일 싸지? 개통 사고 안 나나?\"</td>\r\n<td>\"빨리, 실패 없이 끝나길\"</td>\r\n<td>\"평소엔 존재감 없길\" — 접촉 필요 자체가 부정 경험</td>\r\n<td>\"더 싼 곳 나왔네\" vs \"옮기기 귀찮다\"</td>\r\n</tr>\r\n<tr>\r\n<td>주요 페인포인트</td>\r\n<td>알뜰폰 브랜드 간 구분 불가</td>\r\n<td>프로모션 조건 복잡(종료 후 요금 점프), 망별 차이 이해 어려움</td>\r\n<td>개통 지연, 인증 실패, (2025년 유심 사태 후) 상담 폭주</td>\r\n<td><strong>고객센터 연결 어려움</strong>, 사용량 조회 오류, 평일만 운영</td>\r\n<td>해지 절차 안내 부족 — 위약금이 없어 이탈 장벽 제로</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<p>이 여정 구조는 1부 6장의 KSF ⑤(플랫폼 노출)·⑥(리텐션)과 정확히 맞물린다. 인지~고려 단계의 지배 접점이 비교 플랫폼인 이상, 사업자가 투자할 수 있는 곳은 <strong>개통 경험의 완성도, 사용 중 '무존재감'의 유지, 그리고 프로모션 종료 시점의 이탈 방어</strong>뿐이다.</p>\r\n</section><section class=\"card card--sky\"><div class=\"sess-head\"><span class=\"sess-no\">16</span><div class=\"sess-title\">13장 만족도 순위의 진실</div></div>\r\n<p><strong>이 장의 핵심: 알뜰폰의 만족도·평판 '1위' 타이틀은 프로모션 자본이 좌우하는 임차 자산이다. 순위를 지속 역량으로 읽으면 판단을 그르친다.</strong></p>\r\n<h3>브랜드평판지수 — 언급량의 함정</h3>\r\n<p>한국기업평판연구소의 알뜰폰 브랜드평판지수에서 프리티는 2026년 6월 1위(714,399)에 올랐다. 그러나 시계열을 펼치면 해석이 달라진다.</p>\r\n<div class=\"tbl-wrap\"><table>\r\n<thead>\r\n<tr>\r\n<th>시점</th>\r\n<th>프리티 순위</th>\r\n<th>1위 브랜드</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>2025년 4월</td>\r\n<td>4위</td>\r\n<td>KT엠모바일</td>\r\n</tr>\r\n<tr>\r\n<td>2025년 7월</td>\r\n<td>2위</td>\r\n<td>KT엠모바일</td>\r\n</tr>\r\n<tr>\r\n<td>2026년 4월</td>\r\n<td>2위(697,217)</td>\r\n<td>KT엠모바일(851,827)</td>\r\n</tr>\r\n<tr>\r\n<td>2026년 6월</td>\r\n<td><strong>1위(714,399, +2.46%)</strong></td>\r\n<td>— (2위 KT엠모바일 587,398, <strong>-31.04%</strong>)</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<p>1위 등극의 상당 부분은 프리티의 상승(+2.46%)이 아니라 <strong>경쟁사의 급락(-31.04%)에 따른 반사효과</strong>다. 게다가 평판지수는 참여·소통·커뮤니티 지수를 합산한 <strong>빅데이터 '언급량' 기반 지표</strong>로, 긍정·부정을 정밀하게 구분하지 않는다. 프로모션이나 이슈로 언급이 늘면 지수가 오르는 구조이고, 월별 변동성도 극심하다. \"2026년 6월 단월 1위(직전 2위)\"가 정확한 인용이다.</p>\r\n<h3>체감 만족도 — 더 믿을 만한, 그러나 역시 흔들리는 지표</h3>\r\n<p>실이용자 3만 226명을 조사하는 컨슈머인사이트 체감 만족도는 평판지수보다 소비자 실태를 잘 반영한다. 여기서도 순위의 유동성은 못지않다.</p>\r\n<div class=\"tbl-wrap\"><table>\r\n<thead>\r\n<tr>\r\n<th>시점</th>\r\n<th>알뜰폰 만족도 1위</th>\r\n<th>프리티</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>2024년 하반기</td>\r\n<td>KB리브모바일(8반기 연속 1위 행진 중)</td>\r\n<td>2위</td>\r\n</tr>\r\n<tr>\r\n<td>2025년 상반기</td>\r\n<td>KB리브모바일(705점)</td>\r\n<td>5위(700점)</td>\r\n</tr>\r\n<tr>\r\n<td>2025년 하반기</td>\r\n<td><strong>프리티(719점, 사상 첫 1위)</strong></td>\r\n<td>1위</td>\r\n</tr>\r\n<tr>\r\n<td>2026년 상반기</td>\r\n<td>우리WON모바일(735점)</td>\r\n<td>3위(716점)</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<p>주목할 것은 1위의 교체 패턴이다. 리브모바일(KB국민은행) → 프리티 → 우리WON모바일(우리은행). 은행계 사업자가 프로모션 자본력으로 만족도 순위 자체를 '구매'하는 패턴 — 본서는 이를 <strong>\"만족도 순위의 금융화\"</strong>라 부른다 — 이 확립되고 있다(부산일보, 2026년 6월). 리브모바일이 마케팅에 제동을 걸자 7위로 추락한 것이 방증이다. 만족도 상위권의 실체가 상당 부분 '가격 프로모션 만족'이라는 뜻이며, 자본력이 열위인 독립계에는 지속가능성 리스크다.</p>\r\n<h3>소비자 리뷰의 실상 — \"요금 만족 vs CS 불만\"의 비대칭</h3>\r\n<p>프리티의 모요 평점 4.3/5.0(리뷰 1,604건)이 보여주듯 알뜰폰 상위권의 리뷰 프로파일은 전형적이다. 긍정 축은 가성비·요금 만족. 부정 축은 ① 고객센터 연결 어려움(최다) ② 프로모션 종료 후 요금 점프(\"7개월 0원 → 이후 2만 4,200원\") ③ 앱 사용량 조회 오류 ④ 할인 종료와 동시에 이탈하는 체리피킹이다. 요금 축에서는 업계 최상위, CS 축에서는 평균 이하 — 이 비대칭 구조는 13장의 결론이자 5부 사례 연구의 복선이다.</p>\r\n</section><section class=\"card card--orange\"><div class=\"sess-head\"><span class=\"sess-no\">17</span><div class=\"sess-title\">14장 소비자가 진짜 원하는 것 — JTBD</div></div>\r\n<p><strong>이 장의 핵심: '싸게 쓰고 싶다'는 욕구는 완전히 상향평준화되어 더 이상 차별화 수단이 아니다. 미충족 수요는 '가족 회선 통합 관리'와 '프로모션이 끝나도 재탐색이 필요 없는 요금 설계' 두 곳에 있다.</strong></p>\r\n<p><strong>JTBD(Jobs-to-be-Done)</strong>는 소비자가 제품을 '고용'해서 해결하려는 과업이 무엇인지를 묻는 분석 틀이다. 주요 결과만 추린다.</p>\r\n<div class=\"tbl-wrap\"><table>\r\n<thead>\r\n<tr>\r\n<th>Job 유형</th>\r\n<th>Job 서술</th>\r\n<th>현재 해결책</th>\r\n<th>불완전한 점(기회)</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>기능적</td>\r\n<td>통신비를 절반 이하로 줄이고 싶다</td>\r\n<td>알뜰폰 최저가 요금제</td>\r\n<td>프로모션 종료 후 요금 점프로 재탐색 비용 발생</td>\r\n</tr>\r\n<tr>\r\n<td>기능적</td>\r\n<td>약정 없이 언제든 갈아탈 자유를 갖고 싶다</td>\r\n<td>무약정 알뜰폰 + 자급제</td>\r\n<td>자유 = 사업자에겐 이탈 리스크. \"머물 이유\"는 아무도 안 준다</td>\r\n</tr>\r\n<tr>\r\n<td>기능적</td>\r\n<td><strong>가족 회선을 망 상관없이 한 곳에서 관리하고 싶다</strong></td>\r\n<td><strong>사실상 부재</strong></td>\r\n<td>복수망 사업자만 풀 수 있는 미충족 Job — 통합 청구·가족 혜택 미비</td>\r\n</tr>\r\n<tr>\r\n<td>기능적</td>\r\n<td>업무용/개인용 번호를 싸게 분리하고 싶다</td>\r\n<td>eSIM 듀얼심 + 초저가 요금제</td>\r\n<td>즉시개통·관리 UX 미성숙</td>\r\n</tr>\r\n<tr>\r\n<td>감정적</td>\r\n<td>통신사에 \"호구 잡히지 않았다\"는 통제감을 느끼고 싶다</td>\r\n<td>알뜰폰 전환 자체</td>\r\n<td>개통 사고·CS 불통 시 통제감이 배신감으로 반전</td>\r\n</tr>\r\n<tr>\r\n<td>감정적</td>\r\n<td>(해킹 사고 후) 내 유심·개인정보가 안전하다고 느끼고 싶다</td>\r\n<td>유심 교체, 통신사 이동</td>\r\n<td><strong>알뜰폰 업계에 보안 신뢰 서사가 전무</strong> — 금융권 브랜드가 선점 중</td>\r\n</tr>\r\n<tr>\r\n<td>사회적</td>\r\n<td>알뜰하되 없어 보이지 않게 소비하고 싶다</td>\r\n<td>\"짠테크\" 담론 확산으로 낙인 소멸 중</td>\r\n<td>시니어층엔 \"싸구려\" 잔상 일부 잔존</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<p>3부의 결론: 시장의 지배적 Job(\"싸게\")은 모두가 풀었다. 남은 것은 <strong>① 가족 회선 통합 관리(복수망 자산이 필요한 Job) ② 요금의 정직한 착지 설계(리텐션과 직결) ③ 보안·신뢰(아직 주인 없는 서사)</strong> 세 가지다. 이 세 가지가 4부의 트렌드, 5부의 생존 전략과 어떻게 연결되는지가 이 책 후반부의 줄기다.</p>\r\n<hr />\r\n</section><div class=\"day-divider\"><span class=\"d-badge\">4부 미래</span><span class=\"d-title\">트렌드와 시나리오</span></div><div class=\"intro\"><blockquote>\r\n<p>4부는 다음 3년을 결정할 힘들을 다룬다. 거시 환경의 여섯 영역을 훑고(15장), 기술의 현재 위치를 점검한 뒤(16장), 2028년까지의 세 갈래 시나리오를 그린다(17장). 결론을 미리 말하면 — 이 시장의 운명은 기술이 아니라 정책과 MNO의 전략적 선택이 결정한다.</p>\r\n</blockquote></div><section class=\"card card--violet\"><div class=\"sess-head\"><span class=\"sess-no\">18</span><div class=\"sess-title\">15장 여섯 가지 힘의 이동</div></div>\r\n<p><strong>이 장의 핵심: 결정적 변수(영향도 5점)는 모두 정치·경제 영역에 몰려 있다. 사업자가 통제할 수 있는 변수는 사회·기술 영역 — 보안 신뢰 선점, 디지털 운영, 리텐션 설계 — 에 있다.</strong></p>\r\n<h3>PESTLE 스캔 — 결정적 변수 요약</h3>\r\n<p><strong>PESTLE</strong>은 정치(P)·경제(E)·사회(S)·기술(T)·법률(L)·환경(E) 여섯 영역에서 거시 변화를 훑는 분석 틀이다. 영향도 4~5점의 핵심 변수만 추린다.</p>\r\n<div class=\"tbl-wrap\"><table>\r\n<thead>\r\n<tr>\r\n<th>영역</th>\r\n<th>트렌드</th>\r\n<th>영향도</th>\r\n<th>기회/위협</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>P</td>\r\n<td>도매대가 사후규제 전환 정착 — 첫 자율협상에서 종량제(RM)만 인하, 수익배분(RS) 동결. 업계·과기정통부 모두 사전규제 부활 목소리</td>\r\n<td><strong>5</strong></td>\r\n<td>위협(제도 향방에 따라 반전 가능)</td>\r\n</tr>\r\n<tr>\r\n<td>P</td>\r\n<td>단통법 폐지 1년 — 플래그십 보조금 시기와 알뜰폰 순유출 동조 확인. 보완 입법 논의 개시</td>\r\n<td><strong>5</strong></td>\r\n<td>위협</td>\r\n</tr>\r\n<tr>\r\n<td>P</td>\r\n<td>전파사용료 90% 감면 확대 + 3년 연장(중소 한정, 2027년 시행 예정)</td>\r\n<td>4</td>\r\n<td><strong>기회</strong></td>\r\n</tr>\r\n<tr>\r\n<td>E</td>\r\n<td>MNO 통합요금제·중저가 공세 — 2만 원대 5G 통합요금제 등장, 알뜰폰과의 가격 격차 역대 최소</td>\r\n<td><strong>5</strong></td>\r\n<td>위협</td>\r\n</tr>\r\n<tr>\r\n<td>E</td>\r\n<td>중소 사업자 수익성 붕괴 → 철수 도미노 — 협회 회장사 세종텔레콤의 12년 만의 철수('스노우맨' 매각 추진) 포함 10개사 이상</td>\r\n<td>4</td>\r\n<td><strong>기회</strong>(통합 주도 시)</td>\r\n</tr>\r\n<tr>\r\n<td>S</td>\r\n<td>만족도 순위의 금융화 — 은행 자본이 프로모션으로 순위를 구매</td>\r\n<td>4</td>\r\n<td>위협</td>\r\n</tr>\r\n<tr>\r\n<td>S</td>\r\n<td>보안·개인정보의 선택 변수화 — SKT 해킹 후 \"싸고 안전하다\"로 기준 이동</td>\r\n<td>4</td>\r\n<td><strong>기회</strong>(선점 시)</td>\r\n</tr>\r\n<tr>\r\n<td>L</td>\r\n<td>금융권 알뜰폰 부수업무 정식화(2025년 4월) — 전 은행 진입 가능</td>\r\n<td>4</td>\r\n<td>위협(위탁 수요는 기회)</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<h3>여섯 개의 핵심 트렌드</h3>\r\n<p><strong>트렌드 1. 시장 성숙화의 고착 — 구조적 순유출.</strong> 1,011만 정점 통과 후의 순유출은 계절성이 아니라 3중 협공 구조의 산물이다: 위에서 보조금(단통법 폐지), 가운데서 MNO 통합요금제, 아래서 다이렉트 3브랜드. 파이 축소는 제로섬 전환을 뜻하고, 신규 CAC는 오르며, 프로모션 추적형 2030 세그먼트부터 회전이 빨라진다. <strong>시사점: 성장 전략의 축을 '신규 획득'에서 '순유출 방어'로 즉시 전환해야 한다.</strong></p>\r\n<p><strong>트렌드 2. 도매대가 거버넌스의 구조 변화.</strong> 원가의 결정 메커니즘이 정부 협상에서 사업자 자율 협상으로 이동했다. 첫 자율협상의 결과(RM만 인하, RS 동결)는 협상력 격차가 곧 원가 격차가 되는 시대의 개막을 알린다. RS 동결은 중·고가 5G 요금제의 원가 개선이 멈췄다는 뜻이기도 하다. <strong>시사점: \"협상력 = 물량 + 연합.\" 소형 사업자는 공동 협상과 규모 확대 없이는 구조적 열위다. 사전규제 부활 입법이 최대 반전 카드.</strong></p>\r\n<p><strong>트렌드 3. 중소 사업자 철수 도미노와 통폐합의 개막.</strong> 협회 회장사의 철수가 신호탄이 됐고 10개사 이상이 시장을 떠났다. 감면 확대(2027년 시행)가 급한 불은 껐지만, <strong>시행 전까지의 2026년 하반기는 \"버티기 vs 매각\" 의사결정이 몰리는 구간 — 매물이 가장 싸게 나오는 시간대</strong>다. 자회사는 규제 리스크로 인수에 소극적이므로, 재편의 주도권은 독립계 대형 사업자에게 열려 있다.</p>\r\n<p><strong>트렌드 4. 금융권의 정식 진입 시대.</strong> 은행 부수업무 승인으로 진입 결정만 남은 상태다. 다만 KB의 사례(누적 적자 600억 원+, 순증 정체)는 자본이 곧 성장이 아님을 보여준다. 금융권의 목적은 통신 수익이 아니라 금융 데이터와 고객 락인이므로, <strong>출혈은 깊지만 운영 헌신은 얕다.</strong> 시사점: 자본전 정면 대응은 금물이고, 오히려 금융권의 약점(통신 운영 역량 부재)을 위탁운영(MVNE) 사업 기회로 전환할 수 있다.</p>\r\n<p><strong>트렌드 5. 보안·신뢰의 선택 변수화.</strong> SKT 유심 해킹은 소비자 선택 기준을 바꾼 사건이다. 통신 선택에서 '망 자체의 리스크'가 처음 인식됐고, 이는 한 번 열리면 닫히지 않는 인식의 문이다(미국 T-Mobile 해킹 이후 보안 마케팅이 통신 광고의 상수가 된 선례). <strong>\"보안 신뢰 브랜드\"의 자리는 아직 공석</strong>이며, 은행 신뢰를 이식받는 금융권과 복수망 사업자가 유력한 선점 후보다.</p>\r\n<p><strong>트렌드 6. 디지털 개통·운영의 세대 교체.</strong> eSIM 셀프개통이 신규 유입의 주 경로가 됐고, AI 콜센터(<strong>AICC</strong>, AI Contact Center)는 금융권·MNO 도입이 끝났지만 알뜰폰 도입 사례는 아직 없다 — 선행자 공백이다. 저ARPU 시장에서는 CS 1건당 비용이 마진을 잠식하므로, <strong>운영 자동화의 완성도가 곧 원가 경쟁력</strong>이다.</p>\r\n</section><section class=\"card card--amber\"><div class=\"sess-head\"><span class=\"sess-no\">19</span><div class=\"sess-title\">16장 기술은 어디까지 왔나</div></div>\r\n<p><strong>이 장의 핵심: 지금 투자할 기술과 보류할 기술의 구분이 명확하다. eSIM·AICC·보안은 즉시, 5G 주력화는 방어적으로, 풀MVNO 설비는 보류.</strong></p>\r\n<div class=\"tbl-wrap\"><table>\r\n<thead>\r\n<tr>\r\n<th>기술</th>\r\n<th>현재 위치(2026년)</th>\r\n<th>채택 판단</th>\r\n<th>투자 규모감</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>eSIM/디지털 개통</td>\r\n<td>신규 가입 주 경로화, 개통비 2,750원 표준</td>\r\n<td><strong>즉시 전면화</strong> — 완성도 승부</td>\r\n<td>소</td>\r\n</tr>\r\n<tr>\r\n<td>AICC/AI 고객센터</td>\r\n<td>MNO·금융권 도입 완료, 구독형 상품 성숙. 알뜰폰 공백</td>\r\n<td><strong>1~2년 내 구독형 도입</strong> — 선행자 포지션</td>\r\n<td>소~중(구독형, 설비투자 회피)</td>\r\n</tr>\r\n<tr>\r\n<td>자체 빌링/차세대 IT</td>\r\n<td>독립계 중 보유사 희소</td>\r\n<td><strong>최우선 내부 과제</strong> — 원가·M&amp;A 전략의 기반</td>\r\n<td>중</td>\r\n</tr>\r\n<tr>\r\n<td>5G 도매(RM/RS)</td>\r\n<td>RS 동결로 중·고가 5G 원가 개선 정지. 알뜰폰 5G 회선은 오히려 감소세(2025년 12월 36.6만)</td>\r\n<td>방어적 최소 라인업 — 주력화는 RS 인하 확인 후</td>\r\n<td>소</td>\r\n</tr>\r\n<tr>\r\n<td>풀MVNO 설비(HLR·교환)</td>\r\n<td>국내 출현 전무. 정부 육성 표방 vs 투자 여력 보유사 \"단 한 곳\" 평가</td>\r\n<td><strong>보류·관망</strong> — 일본 IIJmio 사례상 300만+ 회선에서 경제성 성립</td>\r\n<td>대(비권장)</td>\r\n</tr>\r\n<tr>\r\n<td>보안 기술(유심보호 등)</td>\r\n<td>소비자 인지 급상승, 알뜰폰 표준 부재</td>\r\n<td><strong>저비용 조기 탑재</strong> — 신뢰 서사의 물증</td>\r\n<td>소</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<p>한 가지 주의할 점: 알뜰폰 5G 회선은 1만 원대 20GB 요금제 출시에도 불구하고 감소세다(2025년 6월 43만 → 2025년 12월 36.6만). \"5G 전환 가속\" 같은 서술은 데이터와 맞지 않으며, 5G는 MNO 통합요금제와 정면 충돌하는 구간이라 단독 승부처가 아니라 방어 라인업으로 보는 것이 정확하다.</p>\r\n</section><section class=\"card card--mint\"><div class=\"sess-head\"><span class=\"sess-no\">20</span><div class=\"sess-title\">17장 세 갈래 길 — 2028년까지의 시나리오</div></div>\r\n<p><strong>이 장의 핵심: 기본 시나리오(확률 50%)의 시장은 \"덜 잃는 자가 이기는 시장\"이다. 확률은 계량 모델이 아닌 정책 변수 가중의 자체 판단임을 전제로 읽어야 한다.</strong></p>\r\n<h3>시나리오 A. 낙관 — \"정책 반전 + 질서 있는 재편\" (확률 25%)</h3>\r\n<p>사전규제 부활(또는 점유율 제한법과의 패키지 성립), 전파사용료 감면의 예정대로 시행, 단통법 보완 입법, 순유출의 연내 진정이 겹치는 경로. 회선은 1,030만~1,100만으로 회복되고, 자회사 성장 상한이 생기며 독립계에 순증 공간이 열린다. 중소 매물은 질서 있게 재편된다. 이 경로에서는 원가 개선분을 리텐션과 통합에 투자한 독립계 대형 사업자가 점유율 8~10%까지 올라설 수 있다.</p>\r\n<h3>시나리오 B. 기본 — \"역풍 지속 속 차별화 생존\" (확률 50%)</h3>\r\n<p>사후규제 유지(RS 동결 지속), 점유율 제한법 교착, 감면은 시행되지만 보조금·통합요금제 공세도 지속되는 경로. 시장은 2.0~2.2조 원에서 정체되고 회선은 연 -1% 안팎의 완만한 순감. 만족도 순위의 금융화가 고착되고 중소 철수는 산발적으로 이어진다. <strong>이 시장의 승자는 더 많이 얻는 자가 아니라 덜 잃는 자다</strong> — CAC 규율, 프로모션 절벽 관리, 신뢰 서사 확립, CS 자동화로 잔존율을 지키는 사업자만 흑자를 유지한다.</p>\r\n<h3>시나리오 C. 비관 — \"구조적 침식 + 재무 압박 동시화\" (확률 25%)</h3>\r\n<p>감면 시행 지연·축소, 가격 격차 소멸, 순유출 추세화(월 -1~2만), 금융권 추가 진입에 따른 프로모션 전면전이 겹치는 경로. 휴대폰 회선은 950만 선까지 침식되고 독립계의 절반 이하가 퇴출되거나 헐값에 매물로 나온다. 시장은 자회사 + 금융권 + 극소수 대형 독립계로 재편된다. 이 경로에서 재무가 취약한 사업자는 인수 주체가 아니라 <strong>피인수 대상</strong>으로 전락한다.</p>\r\n<h3>공통 조기 경보 지표</h3>\r\n<p>어느 경로로 갈지는 여섯 개의 관측 지표가 먼저 알려준다. ① 알뜰폰 월별 순증감(과기정통부) ② 플래그십 단말 출시 캘린더와 해지율의 동조화 ③ 사전규제 부활·점유율 제한법 입법 일정 ④ 전파사용료 시행령 개정 진행 ⑤ 금융권 신규 진입 발표 ⑥ MNO 통합요금제 추가 인하. 이 지표들은 5부 21장에서 사업자 단위의 경보 체계로 구체화된다.</p>\r\n<hr />\r\n</section><div class=\"day-divider\"><span class=\"d-badge\">5부 생존 전략</span><span class=\"d-title\">프리티/프리텔레콤 사례 연구</span></div><div class=\"intro\"><blockquote>\r\n<p>앞의 네 부가 시장의 일반 이론이라면, 5부는 그 이론을 한 기업에 적용하는 임상 기록이다. 대상은 독립계 사업자 프리티/프리텔레콤 — 국내에서 유일하게 3사 망을 모두 취급하면서, 동시에 누적결손과 계속기업 불확실성이라는 재무 리스크를 안고 있는, 이 시장의 기회와 위험을 한 몸에 담은 표본이다. 특정 기업의 사례이나, 도출되는 생존 조건과 로드맵의 골격은 모든 독립계 사업자에게 일반화할 수 있다.</p>\r\n</blockquote></div><section class=\"card card--sky\"><div class=\"sess-head\"><span class=\"sess-no\">21</span><div class=\"sess-title\">18장 국내 유일 3사망 사업자의 초상</div></div>\r\n<p><strong>이 장의 핵심: 프리티의 최대 자산(3사망 통합)과 최다 불만(고객센터 3원화)은 뿌리가 같다. 자산이 순가치를 내려면 통합 운영이라는 스위치를 켜야 한다.</strong></p>\r\n<h3>회사 개요와 시장 위치</h3>\r\n<p><strong>프리티(FreeT)</strong>는 코스피 상장사 ㈜프리티(구 인스코비 — 2026년 6월 상호 변경, LG유플러스망)와 100% 종속회사 ㈜프리텔레콤(SKT·KT망)의 통합 브랜드다. 국내 알뜰폰 중 유일하게 통신 3사 망을 단일 브랜드로 취급한다. 2026년 4월 최대주주가 KS인더스트리(지분 13.71%)로 변경됐다(공시 사항).</p>\r\n<p>시장 점유율은 공표되지 않아 세 방법으로 교차 추정했다. ① 과기정통부 사업자별 통계 인용 자료 기준 프리텔레콤 34.2만 + 프리티 22.2만 = <strong>약 56만 회선</strong>(휴대폰 회선의 약 5.5%) ② 운영사 자기 공표(모요 소개 \"약 70만\")는 선불·휴면 포함 가능성이 높아 상단 참고치 ③ MVNO 부문 매출(2025년 931.6억 원, 연결감사 기준) ÷ 시장 ARPU 역산 시 약 48.5만 회선 상당 — 프리티의 평균 ARPU(약 1.37만 원 역산)가 시장 평균(1.6만 원)보다 낮기 때문으로 해석되며 ①과 정합적이다.</p>\r\n<p><strong>종합: 가입자 기준 5~7%(중심 5.5%), 매출 기준 4~5%. 순위는 알뜰폰 전체 5위권(자회사 4사 다음), 독립계 후불 브랜드 1~2위</strong>(유니컴즈와 경합). MVNO 부문 영업이익률로 회사가 제시하는 9.2%는 부문 배부 기준이 확인되지 않아 \"회사 제시치, 검증 보류\" 단서를 달아 둔다 — 검증치 기준 업계 1위(KT엠모바일 2.8%)의 3배가 넘는 수치이기 때문이다. 다만 시장 전반이 박리·적자인 가운데 부문 흑자를 유지한다는 방향성 자체는 공개 데이터로도 지지된다.</p>\r\n<h3>SWOT — 강점·약점·기회·위협</h3>\r\n<div class=\"tbl-wrap\"><table>\r\n<thead>\r\n<tr>\r\n<th></th>\r\n<th>긍정</th>\r\n<th>부정</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td><strong>내부</strong></td>\r\n<td><strong>S1</strong> 국내 유일 3사망 통합 브랜드(망 선택권·망 리스크 헤지) <strong>S2</strong> 알뜰폰 브랜드평판 1위(2026년 6월 단월 — 13장의 단서 병기) <strong>S3</strong> 자체 IT·빌링 시스템(상품 설계 유연성, MVNE 확장 잠재력) <strong>S4</strong> MVNO 부문 흑자(이익률 수치는 검증 보류) <strong>S5</strong> 중소 지위 — 전파사용료 90% 감면 대상 + 도매대가 보호 <strong>S6</strong> eSIM·해외유심·선불·B2B/M2M 니치 포트폴리오</td>\r\n<td><strong>W1</strong> <strong>누적결손 1,337.7억 원 + 계속기업 불확실성(감사보고서 강조사항) — 최대 약점</strong> <strong>W2</strong> 2026년 1분기 영업적자 -15.1억 원(마케팅 확대) — 성장-수익 트레이드오프 재진입 <strong>W3</strong> 규모 열위: 통합 56만 vs 1위 170만 <strong>W4</strong> 전환사채 등 잠재 매도 물량(오버행) 부담 + 최대주주 변경 직후의 지배구조 불확실성 <strong>W5</strong> 5G·중고가 라인업 얇음(저ARPU 체질) <strong>W6</strong> 앱·셀프서비스 편의성 열위 <strong>W7</strong> 법인 이원화(프리티/프리텔레콤)에 따른 전산·마케팅 중복 비용</td>\r\n</tr>\r\n<tr>\r\n<td><strong>외부</strong></td>\r\n<td><strong>O1</strong> 도매대가 인하(2025년 1월)로 중용량 요금제 설계 여지 <strong>O2</strong> 전파사용료 90% 감면 — 자회사가 못 갖는 구조적 원가 격차 <strong>O3</strong> 점유율 제한법 성립 시 독립계 반사이익 <strong>O4</strong> 중소사 매물화 — 독립계 통합(M&amp;A) 주도 기회 <strong>O5</strong> 해킹 사고 후 '망 신뢰' 이슈 — 3사망 선택권의 가치 부상 <strong>O6</strong> 외국인·eSIM·세컨드심·B2B 수요 성장</td>\r\n<td><strong>T1</strong> 단통법 폐지 보조금 경쟁 — 시장 순유출, 48% 조건부 이탈 의향 <strong>T2</strong> MNO 다이렉트 3브랜드의 상단 수요 잠식 <strong>T3</strong> 도매대가 사후규제 아래 협상력 열위 <strong>T4</strong> 자본 뒷배 있는 저가 공격수(미디어로그)와의 소모전 <strong>T5</strong> 금융권 자본의 마케팅 재점화 <strong>T6</strong> 감면·중소 지위 요건 변경이라는 정책 리스크 — 원가 우위의 원천이 정부 정책</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<h3>자산과 불만의 역설</h3>\r\n<p>3부에서 본 프리티의 소비자 프로파일 — 요금 만족 최상위, CS 불만 최다 — 을 SWOT 위에 겹치면 이 회사의 구조적 딜레마가 드러난다. <strong>핵심 자산인 3사망 통합(S1)이 소비자 접점에서는 고객센터 3원화(망별 대표번호 3개, 평일만 운영)라는 최다 불만으로 발현된다.</strong> 자산과 불만의 뿌리가 같은 것이다. 통합 CS 접점 없이 3사망은 순가치를 내지 못하고, 반대로 CS 통합이 완성되는 순간 — 자회사는 자사망에 종속돼 있어 — 경쟁사가 구조적으로 모방할 수 없는 자산이 된다. <strong>CS 통합은 비용 절감 과제가 아니라 핵심 차별화의 활성화 스위치다.</strong></p>\r\n<p>같은 논리로, 2부 9장의 두 화이트스페이스(\"믿을 수 있는 최저가\", \"망 선택권\")에 가장 근접한 사업자가 프리티라는 사실도 확인된다. 감면 원가 우위(S5) + 평판 자산(S2) + 3사망(S1)의 조합은 업계에서 유일하다. 문제는 이 잠재력이 W1(재무)이라는 관문 뒤에 갇혀 있다는 점이다.</p>\r\n</section><section class=\"card card--orange\"><div class=\"sess-head\"><span class=\"sess-no\">22</span><div class=\"sess-title\">19장 일곱 가지 생존 조건</div></div>\r\n<p><strong>이 장의 핵심: 일곱 조건에는 위계가 있다. 재무 정상화(조건 1)가 관문이고, 리텐션·통합 운영(조건 3·4)이 손익 엔진이며, 규모·협상력(조건 2·5)이 구조를 바꾸고, 정책 이후 대비와 ARPU 다변화(조건 6·7)가 지속가능성을 만든다.</strong></p>\r\n<p>1부의 KSF 7개와 4부의 트렌드 시사점을 통합하고 소비자 실증(3부)과 재무 현실로 보정한 결과다. 진단은 충족/부분충족/미충족.</p>\r\n<h3>조건 1. 재무 정상화 — 계속기업 불확실성 해소 (모든 조건의 관문) — 미충족</h3>\r\n<p><strong>계속기업 불확실성</strong>이란 감사인이 \"이 회사가 앞으로 정상적으로 사업을 계속할 수 있을지 의문이 있다\"고 감사보고서에 명시하는 강조사항이다. 통폐합 국면에서 이 꼬리표를 달고 있는 사업자는 인수 주체가 아니라 매물로 분류되고, 시장 역풍기에는 자금 조달 창구가 먼저 닫힌다. 누적결손 1,337.7억 원, 1분기 영업적자, 오버행 부담이라는 현재 상태에서, <strong>분기 영업흑자 복귀와 감사 강조사항 해소가 다른 모든 전략의 전제 조건</strong>이다. 신규로 조달하는 자금이 있다면 그 용처 설계가 격차 해소의 유일한 지렛대다.</p>\r\n<h3>조건 2. 규모 임계점 도달 — 100만 회선(점유율 약 10%) — 미충족</h3>\r\n<p>영업이익률 0~3%의 박리 시장에서 고정비 흡수와 도매 선구매 협상력은 회선 수가 결정한다. 현재 56만은 1위의 3분의 1이고, 순유출 시장에서 유기적 순증만으로 100만 도달은 불가능하다. 경로는 두 가지 — 리텐션으로 하한을 지키면서, 15~25만 규모대 사업자 2~3곳의 통폐합으로 점프하는 것. 매물화가 진행 중인 2026년 하반기가 시간 창이다.</p>\r\n<h3>조건 3. 리텐션 중심 사업모델 전환 — 미충족</h3>\r\n<p>이탈 트리거는 이미 특정돼 있다: 프로모션 종료 시점(가입 후 7개월, \"M+7\")의 요금 절벽. 신규 CAC 전쟁 재참전은 순유출 국면에서 회수 불가능한 베팅이다. 필요한 것은 ① CAC 회수기간 상한 규율(예: 12개월) ② 프로모션 종료 후 요금의 완만한 착지 설계 ③ 장기고객 자동 할인·가족결합 ④ 가입 코호트별 이탈 계기판이다.</p>\r\n<h3>조건 4. 통합 운영체계 — CS 단일화 + 법인/전산 통합 — 미충족</h3>\r\n<p>18장의 \"활성화 스위치\" 논의 그대로다. 단일 대표번호 + 구독형 AICC + 콜백, 프리티·프리텔레콤 전산/CS 통합, 셀프서비스 앱 안정화. 법인 이원화의 중복 비용을 없애야 감면·도매 원가 효과가 온전히 손익으로 전환된다.</p>\r\n<h3>조건 5. 도매 원가·협상력 확보 — 부분충족</h3>\r\n<p>3사망 복수 소싱(경쟁 입찰 지렛대)과 자체 빌링은 보유했으나, 단독 56만 물량으로는 선구매 커밋 협상력이 미달이다. 독립계 공동 협상 주도, 통폐합에 의한 물량 확대(조건 2와 직결), 사전규제 부활 입법의 추적이 과제다.</p>\r\n<h3>조건 6. 정책 수혜 자격 유지 + \"정책 이후\"의 자산 구축 — 부분충족</h3>\r\n<p>독립계의 원가 격차는 정책이 만든 것이고, 그 절반(도매대가 축)은 사후규제 전환으로 이미 약화됐다. 남은 감면 축도 시행령 개정이라는 관문이 남았다. 정책 수혜를 지키는 노력과 동시에, <strong>정책이 사라져도 남는 자산 — 브랜드 신뢰, 보안 서사, 자체 전산 — 으로의 전환</strong>을 진행해야 한다. 수상 이력(\"1위\" 타이틀들)을 순위 경쟁이 아니라 신뢰 서사(\"3사망 다 되는 알뜰폰\")로 번역하는 골든타임은 2026년 하반기다.</p>\r\n<h3>조건 7. ARPU 다변화 — MNO 비경합 니치에서 — 부분충족</h3>\r\n<p>평균 ARPU 1.37만 원(역산)은 시장 평균 이하다. 다만 5G 정면 승부는 RS 동결·통합요금제 국면에서 불리하고, 풀MVNO 설비는 시기상조다. 현실적 경로는 eSIM 세컨드심, 외국인 선불, B2B/M2M, 그리고 금융권 대상 MVNE 위탁운영의 상품화다.</p>\r\n<blockquote>\r\n<p><strong>조건 간 위계</strong>: 조건 1(재무)이 관문 → 조건 3·4(리텐션·통합 운영)가 손익 엔진 → 조건 2·5(규모·협상력)가 구조 개선 → 조건 6·7(정책 이후·ARPU)이 지속가능성. 1부 6장의 요약(\"①~④ 없이는 이익 불가, ⑤~⑦ 없이는 성장 불가\")과 정합한다.</p>\r\n</blockquote>\r\n</section><section class=\"card card--violet\"><div class=\"sess-head\"><span class=\"sess-no\">23</span><div class=\"sess-title\">20장 3단계 생존 로드맵</div></div>\r\n<p><strong>이 장의 핵심: 로드맵의 순서가 곧 논리다. 지혈(재무·이탈)이 먼저고, 통합(CS·전산)이 다음이며, 확장(통폐합·신사업)은 마지막이다. 순서를 건너뛰면 확장이 지혈을 삼킨다.</strong></p>\r\n<h3>Phase 1. 즉시(0~6개월) — \"지혈과 재장전\"</h3>\r\n<p>목표: 분기 영업흑자 복귀 가시화 + 이탈 출혈 지점 봉합 + 통폐합 기회 정찰.</p>\r\n<ul>\r\n<li><strong>신규 조달 자금의 용처 원칙 확립</strong> — 권장 배분: 손익분기 방어·운전자금 약 40%, 전산/CS 통합 및 AICC 약 30%, 경자산 인수(가입자 이관)·MVNE 준비 약 20%, 예비 약 10%. <strong>신규 CAC 프로모션 투입 금지</strong>가 원칙의 핵심이다.</li>\r\n<li>CAC 회수기간 상한 규율(12개월) 도입 — 신규 프로모션 손익 심사 게이트.</li>\r\n<li>M+7 요금 절벽 해소 — 착지 요금 재설계 + 종료 60일 전 선제 안내·전환 제안.</li>\r\n<li>코호트 이탈 대시보드와 해지자 사유 서베이 가동(\"48% 이탈 의향 → 실제 전환율\"의 갭 측정).</li>\r\n<li>유심보호 서비스 전 요금제 기본 탑재 — 보안 서사의 저비용 물증.</li>\r\n<li>15~25만 규모대 매물 후보 접촉 개시 — 감면 시행 전이 매물 최저가 구간.</li>\r\n</ul>\r\n<p>핵심 KPI: 월 순증감을 시장 순유출률 이하로 방어, M+7 코호트 잔존율 +10%p, 2026년 4분기 영업흑자 전환, 마케팅비/매출 비율 전년 동기 대비 -20%.</p>\r\n<h3>Phase 2. 단기(6~18개월) — \"통합 완성과 서사 전환\"</h3>\r\n<p>목표: 통합 CS·전산 완성으로 3사망 자산 활성화 + 감면 재원의 리텐션 전환 + 첫 비유기적 성장.</p>\r\n<ul>\r\n<li>고객센터 단일 대표번호 통합 + 구독형 AICC 도입(알뜰폰 업계 선행자 포지션) + 콜백·챗봇 선처리, 앱 사용량 조회 안정화.</li>\r\n<li>프리티·프리텔레콤 전산/CS 통합 — 법인 이원화 중복 비용 해소.</li>\r\n<li>전파사용료 90% 감면 시행(2027년) 재원 — 보수적으로 연 20억 원 이상으로 추정 — 을 <strong>장기고객 자동할인·가족결합에 전액 투입</strong>. 신규 보조금 투입 금지.</li>\r\n<li>\"믿을 수 있는 최저가 + 망 선택권\" 캠페인 — 망 전환 보장 프로그램(위약금 없이 망 변경) 상품화, \"3사망 다 되는 알뜰폰\"의 소비자 언어화.</li>\r\n<li>가족 통합 관리 상품 출시 — 복수 회선·복수 망 통합 청구(3부 14장의 유일한 미충족 Job).</li>\r\n<li>소형사 1건 가입자 이관형 인수 실행(경자산 방식 우선).</li>\r\n<li>금융권 대상 MVNE/위탁운영 B2B 제안 개시, 독립계 공동 도매 협상 주도.</li>\r\n</ul>\r\n<p>핵심 KPI: CS 불만 언급률 50% 감소, 고객센터 응답률 90%+, 연간 영업흑자(연결), 가입자 60만+ 회복, 가족결합 5만 회선, <strong>감사보고서 계속기업 강조사항 해소</strong>.</p>\r\n<h3>Phase 3. 중기(18~36개월) — \"독립계 구심점과 구조적 지위\"</h3>\r\n<p>목표: 80~100만 회선(점유율 8~10%) 도달로 도매 협상 지위 격상 + ARPU 믹스 개선 + 신사업 수익화.</p>\r\n<ul>\r\n<li>통폐합 2~3건 누적 — 자체 빌링으로 이관 원가를 최소화하는 인수 후 통합(PMI).</li>\r\n<li>물량 기반 선구매 커밋 + 3사망 경쟁 입찰 구도 상시화.</li>\r\n<li>ARPU 믹스 개선 — 목표 평균 ARPU 1.37만 → 1.5만 원(세컨드심·선불·B2B).</li>\r\n<li>MVNE 수주 1건 이상 실현 — 자체 빌링의 플랫폼화.</li>\r\n<li>5G는 방어 라인업 유지, 풀MVNO 설비 투자 보류 지속.</li>\r\n</ul>\r\n<p>핵심 KPI: 가입자 80만+(점유율 8%+), MVNO 부문 영업이익률 5%+ 안정화, 평균 ARPU 1.5만 원, 도매대가 실효 인하율 업계 평균 초과.</p>\r\n<p>각 Phase는 앞 단계의 성공을 선행 조건으로 삼는다. Phase 2의 감면 재원 투입과 인수 실행은 Phase 1의 흑자 전환이, Phase 3의 통폐합 누적은 Phase 2의 연간 흑자와 강조사항 해소가 전제다.</p>\r\n</section><section class=\"card card--amber\"><div class=\"sess-head\"><span class=\"sess-no\">24</span><div class=\"sess-title\">21장 조기 경보와 컨틴전시</div></div>\r\n<p><strong>이 장의 핵심: 정책·경쟁 변수가 시장을 결정하는 구조에서는 감지 속도가 곧 전략이다. 경보 지표에 임계값과 대응을 미리 묶어 두면, 위기는 대응 매뉴얼의 실행 문제가 된다.</strong></p>\r\n<h3>조기 경보 지표 9종 (월별/분기별 추적)</h3>\r\n<div class=\"tbl-wrap\"><table>\r\n<thead>\r\n<tr>\r\n<th>#</th>\r\n<th>지표</th>\r\n<th>주기</th>\r\n<th>임계값(경보 발동)</th>\r\n<th>대응</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>1</td>\r\n<td>알뜰폰 전체 순증감(과기정통부)</td>\r\n<td>월</td>\r\n<td>3개월 연속 월 -1.5만 이하</td>\r\n<td>순유출 추세화 판정 → 비관 시나리오 프로토콜 예열, 마케팅 지출 즉시 -30%</td>\r\n</tr>\r\n<tr>\r\n<td>2</td>\r\n<td>자체 해지율 × 플래그십 출시 캘린더</td>\r\n<td>월</td>\r\n<td>해지율이 직전 6개월 평균 +30% 초과</td>\r\n<td>해당 월 한정 리텐션 오퍼(요금 할인형), 신규 CAC 동결</td>\r\n</tr>\r\n<tr>\r\n<td>3</td>\r\n<td>M+7 코호트 잔존율</td>\r\n<td>월</td>\r\n<td>개선폭 2분기 연속 목표 미달</td>\r\n<td>착지 요금 2차 개정, 프로모션 구조 재검토</td>\r\n</tr>\r\n<tr>\r\n<td>4</td>\r\n<td>사전규제 부활·점유율 제한법 입법 일정</td>\r\n<td>분기</td>\r\n<td>법사위 상정·본회의 일정 공지</td>\r\n<td>시나리오별 사업 영향 시뮬레이션 가동</td>\r\n</tr>\r\n<tr>\r\n<td>5</td>\r\n<td>전파사용료 시행령 개정 진행</td>\r\n<td>분기</td>\r\n<td>2026년 4분기까지 입법예고 미개시 또는 감면율 축소</td>\r\n<td>감면 전제 리텐션 재원 축소·연기, 전산 통합 절감으로 대체</td>\r\n</tr>\r\n<tr>\r\n<td>6</td>\r\n<td>금융권 신규 진입 발표(신한·하나 등)</td>\r\n<td>상시</td>\r\n<td>진입 공식 발표</td>\r\n<td>2주 내 MVNE 위탁운영 선제 제안 — 프로모션 정면 대응 금지</td>\r\n</tr>\r\n<tr>\r\n<td>7</td>\r\n<td>MNO 통합요금제·다이렉트 요금 인하</td>\r\n<td>월</td>\r\n<td>실효 요금 격차 20% 미만 상품 등장</td>\r\n<td>가격 매칭 금지 — 3사망·보안·가족결합 비가격 축으로 방어</td>\r\n</tr>\r\n<tr>\r\n<td>8</td>\r\n<td>도매대가 자율협상 결과(RM/RS)</td>\r\n<td>라운드별</td>\r\n<td>RS 동결 2라운드 연속</td>\r\n<td>5G 중용량 확대 계획 동결 유지, 공동 협상 카드 강화</td>\r\n</tr>\r\n<tr>\r\n<td>9</td>\r\n<td>자사 유동성(현금+미사용 한도)</td>\r\n<td>월</td>\r\n<td>6개월 운영자금 미만</td>\r\n<td>컨틴전시 Plan B 즉시 발동</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<h3>컨틴전시 — 비관 시나리오 대응</h3>\r\n<p>발동 조건: 경보 1(순유출 추세화)·5(감면 지연)·9(유동성) 중 2개 이상 동시 점등, 또는 감사의견 변형 발생.</p>\r\n<div class=\"tbl-wrap\"><table>\r\n<thead>\r\n<tr>\r\n<th>리스크</th>\r\n<th>Plan B</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td>순유출 추세화 + 프로모션 전면전 강요</td>\r\n<td>마케팅 즉시 축소·현금 보존. 회전문 세그먼트(2030 프로모션 추적형) 포기, 선불·외국인·B2B 등 비경합 니치로 후퇴 집중. 목표를 \"점유율 방어\"에서 \"부문 흑자 사수\"로 전환</td>\r\n</tr>\r\n<tr>\r\n<td>감면 축소·지연으로 원가 우위 소멸</td>\r\n<td>리텐션 재원을 감면이 아닌 전산 통합 절감분으로 대체. 도매 공동 협상·경쟁 입찰로 원가 방어 축 이동</td>\r\n</tr>\r\n<tr>\r\n<td>자금 조달 차질</td>\r\n<td>자산 경량화(비핵심 부문 매각 검토), 인수 계획 전면 동결, 운전자본 회전 개선. 실적 가시성 확보 전 추가 전환성 조달 자제</td>\r\n</tr>\r\n<tr>\r\n<td>피인수 국면 전락(적자 고착+유동성 압박)</td>\r\n<td><strong>3사망·자체 전산 자산의 가치가 남아 있을 때</strong> 전략적 파트너(금융권·플랫폼) 지분 제휴를 선제 추진 — 헐값 매각 회피가 목표. 우선순위: ① 소수 지분+MVNE 장기 계약 ② 합작 ③ 경영권 매각(최후)</td>\r\n</tr>\r\n<tr>\r\n<td>특정 망 대형 사고 재발</td>\r\n<td>위기를 기회로 — 망 전환 보장 프로그램 즉시 전면 홍보. 단, 자사 CS 폭주 대비 AICC 오버플로 리허설 선행</td>\r\n</tr>\r\n<tr>\r\n<td>인수 실패·PMI 부실</td>\r\n<td>추가 인수 동결, 이관형(경자산) 방식 회귀. 인수 대신 MVNE 위탁으로 규모 효과 대체</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<hr />\r\n</section><div class=\"day-divider\"><span class=\"d-badge\">에필로그</span><span class=\"d-title\">덜 잃는 자가 이기는 시장</span></div><div class=\"intro\"><p>책을 닫기 전에, 다섯 개의 부를 관통한 발견을 다섯 문장으로 정리한다.</p>\r\n<p><strong>첫째, 자산과 불만의 뿌리가 같을 수 있다.</strong> 프리티의 3사망 통합은 업계 유일의 차별화 자산이면서 동시에 최다 불만(고객센터 3원화)의 원인이다. 구조적 강점은 운영이 받쳐 줄 때만 강점이다 — 이것은 프리티만의 교훈이 아니라, \"우리의 강점은 무엇인가\"를 묻는 모든 기업이 곱씹을 명제다.</p>\r\n<p><strong>둘째, 정책이 준 우위는 정책이 거둬 갈 수 있다.</strong> 독립계의 원가 우위는 시장이 아니라 규제가 만든 것이고, 그 절반(도매대가 축)은 사후규제 전환으로 이미 흔들렸다. 정책 수혜를 지키는 노력과, 정책이 사라져도 남는 자산(신뢰·전산·규모)으로의 전환은 동시에 진행돼야 한다.</p>\r\n<p><strong>셋째, 순유출 시장의 승부처는 신규 획득이 아니라 이탈의 문턱이다.</strong> 이 시장에서 이탈 트리거는 프로모션 종료 시점의 요금 절벽으로 이미 특정돼 있다. 획득 경쟁에 쓸 돈을 착지 요금 설계와 장기 고객 우대로 돌리는 것이 순유출 국면의 유일한 양(+)의 기댓값 전략이다.</p>\r\n<p><strong>넷째, 순위는 임차 자산이다.</strong> 만족도·평판 1위 타이틀은 프로모션 자본이 좌우하며, 자본이 끊기는 순간 반납된다. 수상 이력은 순위 유지 경쟁의 연료가 아니라 신뢰 서사로 번역할 재료로만 써야 한다.</p>\r\n<p><strong>다섯째, 통폐합의 문은 열렸고, 문 앞에 설 자격은 재무가 결정한다.</strong> 시장 재편 국면에서 인수자와 매물을 가르는 것은 전략의 우열이 아니라 계속기업 꼬리표의 유무다. 재무 정상화가 모든 전략의 관문이라는 평범한 결론이, 이 시장에서는 가장 절박한 결론이다.</p>\r\n<p>1,000만 회선은 도착점이 아니라 출발선이었다. 성장의 시대에는 모두가 이길 수 있었지만, 성숙의 시대에는 준비된 소수만 남는다. 알뜰폰의 다음 10년은 — 다시 한 번 — <strong>덜 잃는 자가 이기는 시간</strong>이다.</p>\r\n<hr /></div><div class=\"day-divider\"><span class=\"d-title\">부록 A 용어집</span></div><div class=\"intro\"><div class=\"tbl-wrap\"><table>\r\n<thead>\r\n<tr>\r\n<th>용어</th>\r\n<th>풀이</th>\r\n</tr>\r\n</thead>\r\n<tbody>\r\n<tr>\r\n<td><strong>MVNO</strong> (Mobile Virtual Network Operator)</td>\r\n<td>가상이동통신망사업자. 주파수·망 없이 MNO의 망을 도매로 빌려 자체 브랜드로 재판매하는 사업자. '알뜰폰'의 공식 명칭</td>\r\n</tr>\r\n<tr>\r\n<td><strong>MNO</strong> (Mobile Network Operator)</td>\r\n<td>기간통신사업자. 주파수와 무선망을 직접 보유한 SKT·KT·LG유플러스 3사</td>\r\n</tr>\r\n<tr>\r\n<td><strong>MVNE</strong> (Mobile Virtual Network Enabler)</td>\r\n<td>MVNO에게 빌링·개통·고객관리 등 운영 인프라를 제공하는 사업자 또는 그 기능. 위탁운영 사업의 기반</td>\r\n</tr>\r\n<tr>\r\n<td><strong>풀MVNO</strong></td>\r\n<td>핵심망 일부(HLR·교환 설비 등)를 자체 구축해 도매 종속에서 부분적으로 벗어난 MVNO. 국내 미출현</td>\r\n</tr>\r\n<tr>\r\n<td><strong>도매대가</strong></td>\r\n<td>MVNO가 MNO에게 지불하는 망 사용 도매 요금. 데이터 종량(원/MB) 방식과 수익배분 방식이 있다</td>\r\n</tr>\r\n<tr>\r\n<td><strong>RM / RS</strong></td>\r\n<td>도매대가 산정 방식. RM(Retail Minus 계열의 종량제)은 사용량 단가 기반, RS(Revenue Share)는 소매 요금의 일정 비율을 배분하는 방식. 중·고가 요금제는 주로 RS 기반</td>\r\n</tr>\r\n<tr>\r\n<td><strong>사전규제 / 사후규제</strong></td>\r\n<td>사전규제는 정부가 도매대가 협상을 대신·주도하는 방식, 사후규제는 사업자 간 자율 협상 후 문제 발생 시 정부가 개입하는 방식</td>\r\n</tr>\r\n<tr>\r\n<td><strong>도매제공의무사업자</strong></td>\r\n<td>법령상 MVNO에 망을 의무적으로 도매 제공해야 하는 사업자(현재 SKT)</td>\r\n</tr>\r\n<tr>\r\n<td><strong>ARPU</strong> (Average Revenue Per User)</td>\r\n<td>가입자당 월평균 매출. 통신업 수익성의 기본 지표</td>\r\n</tr>\r\n<tr>\r\n<td><strong>CAC</strong> (Customer Acquisition Cost)</td>\r\n<td>신규 고객 1명 획득에 드는 마케팅·프로모션 비용</td>\r\n</tr>\r\n<tr>\r\n<td><strong>LTV</strong> (Lifetime Value)</td>\r\n<td>고객 1명이 잔존 기간 전체에 걸쳐 가져다주는 이익의 합</td>\r\n</tr>\r\n<tr>\r\n<td><strong>리텐션</strong> (retention)</td>\r\n<td>기존 고객을 유지하는 활동 전반. 잔존율로 측정</td>\r\n</tr>\r\n<tr>\r\n<td><strong>코호트</strong> (cohort)</td>\r\n<td>같은 시기·조건에 가입한 고객 집단. 코호트별 잔존율 분석은 이탈 시점 특정의 기본 도구</td>\r\n</tr>\r\n<tr>\r\n<td><strong>eSIM</strong></td>\r\n<td>단말기 내장형 디지털 유심. 실물 배송 없이 즉시 개통 가능하며 듀얼심(한 단말 두 번호)의 기반</td>\r\n</tr>\r\n<tr>\r\n<td><strong>자급제</strong></td>\r\n<td>통신사 대리점이 아닌 경로로 단말기를 구매해 유심만 끼워 쓰는 방식</td>\r\n</tr>\r\n<tr>\r\n<td><strong>번호이동</strong></td>\r\n<td>전화번호를 유지한 채 통신사를 옮기는 제도</td>\r\n</tr>\r\n<tr>\r\n<td><strong>단통법</strong></td>\r\n<td>이동통신단말장치 유통구조 개선에 관한 법률. 단말 보조금을 규제하던 법으로 2025년 7월 22일 폐지</td>\r\n</tr>\r\n<tr>\r\n<td><strong>전파사용료</strong></td>\r\n<td>주파수 사용 대가로 정부에 내는 준조세. 중소 알뜰폰은 감면 대상(2027년부터 90% 감면 예정)</td>\r\n</tr>\r\n<tr>\r\n<td><strong>IoT / M2M</strong></td>\r\n<td>사물인터넷/사물통신 회선. 커넥티드카·원격관제 등 사람이 아닌 기기가 쓰는 회선</td>\r\n</tr>\r\n<tr>\r\n<td><strong>커넥티드카</strong></td>\r\n<td>통신망에 상시 연결된 자동차. 국내 알뜰폰 IoT 회선의 최대 비중</td>\r\n</tr>\r\n<tr>\r\n<td><strong>AICC</strong> (AI Contact Center)</td>\r\n<td>AI 기반 고객센터. 챗봇·음성봇·상담 보조로 CS 비용을 낮추는 구독형 도입이 확산 중</td>\r\n</tr>\r\n<tr>\r\n<td><strong>0원 요금제</strong></td>\r\n<td>일정 기간(예: 7개월) 요금을 면제하는 프로모션 요금제. 출혈경쟁과 체리피킹 이탈의 원인</td>\r\n</tr>\r\n<tr>\r\n<td><strong>체리피킹</strong></td>\r\n<td>프로모션 혜택만 취하고 종료 시점에 이탈하는 소비 행태</td>\r\n</tr>\r\n<tr>\r\n<td><strong>KSF</strong> (Key Success Factor)</td>\r\n<td>해당 산업에서 생존·성공에 필수적인 핵심 요인</td>\r\n</tr>\r\n<tr>\r\n<td><strong>5 Forces</strong></td>\r\n<td>포터의 산업 구조 분석 틀. 공급자·구매자·신규 진입·대체재·기존 경쟁의 다섯 압력으로 산업 매력도를 진단</td>\r\n</tr>\r\n<tr>\r\n<td><strong>PESTLE</strong></td>\r\n<td>정치·경제·사회·기술·법률·환경 여섯 영역의 거시 환경 분석 틀</td>\r\n</tr>\r\n<tr>\r\n<td><strong>SWOT</strong></td>\r\n<td>강점(S)·약점(W)·기회(O)·위협(T) 분석</td>\r\n</tr>\r\n<tr>\r\n<td><strong>JTBD</strong> (Jobs-to-be-Done)</td>\r\n<td>소비자가 제품을 '고용'해 해결하려는 과업 중심의 수요 분석 틀</td>\r\n</tr>\r\n<tr>\r\n<td><strong>NPS</strong> (Net Promoter Score)</td>\r\n<td>순추천지수. \"지인에게 추천하겠는가\"로 측정하는 충성도 지표</td>\r\n</tr>\r\n<tr>\r\n<td><strong>CR / HHI</strong></td>\r\n<td>시장 집중도 지표. CR-N은 상위 N개사 점유율 합, HHI는 전 사업자 점유율 제곱합</td>\r\n</tr>\r\n<tr>\r\n<td><strong>CAGR</strong></td>\r\n<td>연평균 복합 성장률</td>\r\n</tr>\r\n<tr>\r\n<td><strong>오버행</strong> (overhang)</td>\r\n<td>전환사채 등으로 시장에 나올 수 있는 잠재 매도 물량. 주가·조달의 부담 요인</td>\r\n</tr>\r\n<tr>\r\n<td><strong>계속기업 불확실성</strong></td>\r\n<td>감사인이 기업의 존속 능력에 의문을 표시하는 감사보고서 강조사항</td>\r\n</tr>\r\n<tr>\r\n<td><strong>PMI</strong> (Post-Merger Integration)</td>\r\n<td>인수 후 통합. 전산·조직·고객 이관 등 M&amp;A의 성패를 가르는 실행 단계</td>\r\n</tr>\r\n<tr>\r\n<td><strong>규제샌드박스</strong></td>\r\n<td>신사업에 한시적으로 규제를 유예해 주는 제도. 은행권 알뜰폰 진입의 첫 통로였다</td>\r\n</tr>\r\n<tr>\r\n<td><strong>화이트스페이스</strong></td>\r\n<td>포지셔닝 맵에서 경쟁자가 아직 차지하지 않은 빈 영역</td>\r\n</tr>\r\n</tbody>\r\n</table></div>\r\n<hr /></div><div class=\"day-divider\"><span class=\"d-title\">부록 B 데이터 출처 목록</span></div><div class=\"intro\"><p><strong>정부·공공 통계</strong></p>\r\n<ul>\r\n<li>과학기술정보통신부 무선통신서비스 가입 현황(월별) — 회선 수·순증감의 원천 통계. 원자료 msit.go.kr, 본서는 언론 인용 보도로 확인</li>\r\n<li>KISDI 통신시장 경쟁상황평가 — ARPU, 소매 매출 점유율</li>\r\n<li>공공데이터포털 알뜰폰 사업자 현황(2026년 3월 갱신)</li>\r\n</ul>\r\n<p><strong>시장·가입자 통계 인용 보도</strong></p>\r\n<ul>\r\n<li>ZDNet Korea(2025.8.9), 디지털데일리(2025.8.8), 전자신문(2025.8.13) — 1,000만 돌파</li>\r\n<li>아주경제(2026.6.2) — 2026년 4~5월 순유출, MNO 통합요금제</li>\r\n<li>더스쿠프(2026.5.26) — 이탈 의향 48%, 0원 마케팅</li>\r\n<li>머니투데이(2025.3.29) — 54개사 사업자별 가입자</li>\r\n<li>딜사이트 — 자회사 점유율 47.0%</li>\r\n<li>네이트뉴스·파이낸셜투데이(2024.11.29) — IoT 제외 자회사 점유율 약 49%</li>\r\n</ul>\r\n<p><strong>규제·정책</strong></p>\r\n<ul>\r\n<li>ZDNet·디지털투데이·YTN(2025.1.15), KDI 경제정책자료 — 도매대가 최대 52% 인하</li>\r\n<li>전자신문·디지털데일리·ZDNet(2026.6.26~29) — 전파사용료 90% 감면</li>\r\n<li>디지털데일리·한국경제(2024.12.26), 뉴시스·ZDNet(2025.1.7) — 점유율 제한법 입법 경과</li>\r\n<li>이뉴스투데이·뉴스후플러스·머니투데이(2025.12)·비즈니스포스트 — 도매대가 자율협상(RM 인하·RS 동결)</li>\r\n<li>한국경제(2025.1.21), 더벨(2025.7.22) — 단통법 폐지</li>\r\n<li>뉴스1·아시아경제(2025.4.18) — 금융권 부수업무 승인, 우리WON모바일 출시</li>\r\n</ul>\r\n<p><strong>기업 실적(감사보고서 기반)</strong></p>\r\n<ul>\r\n<li>기업정보 플랫폼 캐치 — KT엠모바일 2024년 매출 3,455.8억 원·영업이익 95.8억 원</li>\r\n<li>뉴스웨이(2026.6.22) — SK텔링크 알뜰폰 부문 1,446.9억 원·구조조정</li>\r\n<li>머니투데이(2025.3.16), 시사저널e — 미디어로그 적자 전환</li>\r\n<li>디지털포스트(2026) — KB리브모바일 누적 적자</li>\r\n<li>프리티 공시·freet.co.kr, 톱스타뉴스(상호 변경) — 프리티/프리텔레콤 개요</li>\r\n</ul>\r\n<p><strong>소비자 조사</strong></p>\r\n<ul>\r\n<li>컨슈머인사이트 이동통신 기획조사(반기, n=30,226) — 아이티데일리(2026.1.6), 부산일보(2026.6.2), 비즈니스포스트(2025.6)</li>\r\n<li>한국기업평판연구소 브랜드평판지수(월간) — 일간투데이·이넷뉴스(2026.6), 파이낸스투데이(2026.4), 더페어(2025.4/7)</li>\r\n<li>모요(모두의요금제) — 프리티 평점 4.3(리뷰 1,604건), 신규 가입 연령 통계</li>\r\n<li>매거진한경(2025.11) — 2025 한국품질만족도</li>\r\n<li>한국경제(2024.8.26) — 이용자 연령 구성, 정보통신신문·디지털데일리 — 자급제 비율</li>\r\n</ul>\r\n<p><strong>트렌드·글로벌</strong></p>\r\n<ul>\r\n<li>글로벌이코노믹(2025.2.25), 에너지경제(2025.1.13), ZDNet(2025.1.6), 아시아타임(2026.5.5) — 중소 사업자 철수</li>\r\n<li>굿모닝경제·전자신문(2025.2), 경향신문(2026.4) — AICC</li>\r\n<li>쿠키뉴스·전자신문·디지털데일리(2025.1) — 풀MVNO 정책</li>\r\n<li>Grand View Research, Fortune Business Insights, Precedence Research, Straits Research, Research and Markets, TBRC — 글로벌 MVNO 시장(2025~2026 리포트)</li>\r\n<li>해외 사례: 일본 IIJmio(풀MVNO 규모 경제), 미국 Mint Mobile(T-Mobile 피인수), 미국 T-Mobile 해킹 후 보안 마케팅</li>\r\n</ul>\r\n<hr /></div><div class=\"day-divider\"><span class=\"d-title\">부록 C 데이터 한계와 정정 이력</span></div><div class=\"intro\"><p>본서의 신뢰성을 위해, 조사 과정의 한계와 정정 사항을 투명하게 남긴다.</p>\r\n<p><strong>1. 비공개 자료 수치의 폐기·정정.</strong> 조사 초기에 참고한 일부 비공개 자료의 경쟁사 실적 수치가 감사보고서 기반 공개 데이터와 대조 결과 상당수 불일치했다(대표 사례: 한 상위 사업자의 매출이 실제의 2배 이상으로 기재 — 인접 행의 수치가 밀려 들어간 오류로 추정). 본서는 해당 표를 전량 폐기하고 감사보고서 기반 검증치로 대체했다. 특정 기업 제시 수치 중 부문 배부 기준이 확인되지 않은 항목(프리티 MVNO 부문 이익률 9.2%)은 \"회사 제시치, 검증 보류\" 단서를 유지했다.</p>\r\n<p><strong>2. 원자료 직접 열람의 한계.</strong> 과기정통부 월별 원자료와 DART 공시 원문 일부는 직접 대조하지 못해 언론 인용 보도로 대체했다. 사업자별 가입자 수는 정부가 정기 공표하지 않아 시점이 혼재된(2024년 12월~2025년 4월) 인용 자료를 사용했고, 점유율 추정 오차 ±1%p를 감안해야 한다.</p>\r\n<p><strong>3. 1차 조사 미실시.</strong> 소비자 분석은 공개 2차 데이터 기반이며, 설문·FGI 등 1차 조사와 커뮤니티 게시글의 계량화는 실시하지 않았다. 불만 테마의 방향성은 복수 소스로 교차 확인했으나 빈도는 미계량이다.</p>\r\n<p><strong>4. 추정치의 성격.</strong> 시장 규모(연 1.9~2.2조 원), 3년 전망, 독립계 점유율(약 45%), 시나리오 확률(25/50/25)은 산출 방법을 명시한 자체 추정이며 계량 모델의 산출물이 아니다.</p>\r\n<p><strong>5. 계속 추적 항목.</strong> ① 점유율 제한법·사전규제 부활 입법 경과 ② 전파사용료 시행령 개정(2026년 하반기) ③ 프리티 분기보고서의 부문별 손익 배부 기준 ④ 경쟁 3사의 2025년 감사보고서 원문 대조.</p></div></div></div><div style=\"max-width:860px;margin:24px auto 40px;padding:14px 18px;border:1px solid #d9d3c6;border-radius:12px;background:#faf8f3;color:#5b6e88;font-size:13px;line-height:1.7;text-align:center;\">내부 배포용 — 재배포 금지 · 정보 제공 목적이며 투자 권유가 아님<br/>본 자료는 선명그룹 내부·제한 배포용입니다. 허용된 독자 범위 외 제3자 전달·공개·게시를 금하며, 외부 인용은 발행처의 사전 서면 동의가 필요합니다.</div></body></html>";
